(function () {
  'use strict';
  const DADOS = [{"n":1,"titulo":"Primeiros passos","topicos":[{"id":"1-entrar-no-painel","titulo":"Entrar no painel","admin":false,"blocos":[{"t":"p","h":"O ZapZap é um painel para usar o WhatsApp do computador ou do celular. Cada pessoa entra com o seu próprio usuário e senha."},{"t":"ol","itens":[{"h":"Abra o endereço do painel no navegador (o administrador informa o link)."},{"h":"Digite o seu <b>Usuário</b> e a sua <b>Senha</b>. Toque no olho para ver a senha que está digitando."},{"h":"Toque em <b>Entrar</b>.","img":"manual/img/login.webp","alt":"Tela de login do ZapZap"},{"h":"Pronto: você cai na página <b>Painel</b>, a página inicial, com o resumo do dia.","img":"manual/img/painel.webp","alt":"Painel inicial com estatísticas e gráfico"}]},{"t":"nota","tipo":"dica","h":"se errar a senha várias vezes seguidas, o painel pede para aguardar alguns minutos antes de tentar de novo."}],"busca":"primeiros passos entrar no painel o zapzap e um painel para usar o whatsapp do computador ou do celular. cada pessoa entra com o seu proprio usuario e senha. abra o endereco do painel no navegador (o administrador informa o link). digite o seu usuario e a sua senha. toque no olho para ver a senha que esta digitando. toque em entrar. pronto: voce cai na pagina painel, a pagina inicial, com o resumo do dia. se errar a senha varias vezes seguidas, o painel pede para aguardar alguns minutos antes de tentar de novo."},{"id":"1-trocar-a-senha-no-primeiro-acesso-quando-o-administrador-exigir","titulo":"Trocar a senha no primeiro acesso (quando o administrador exigir)","admin":false,"blocos":[{"t":"p","h":"A senha que o administrador cria ou gera para você é definitiva: você pode usá-la normalmente. Só se ele marcar a opção <b>Exigir que a pessoa troque a senha no primeiro acesso</b> o painel não deixa você continuar sem criar uma senha só sua."},{"t":"ol","itens":[{"h":"Entre com a senha que o administrador passou."},{"h":"Na janela <b>Defina a sua senha</b>, digite essa senha no primeiro campo (a que você usou para entrar)."},{"h":"Digite a <b>Nova senha (mínimo 6 caracteres)</b> e repita em <b>Repita a nova senha</b>."},{"h":"Toque em <b>Salvar nova senha</b>.","img":"manual/img/senha-obrigatoria.webp","alt":"Janela para definir a senha no primeiro acesso"}]},{"t":"nota","tipo":"aviso","h":"a nova senha precisa ter pelo menos 6 caracteres e ser diferente da anterior. Se você tocar em <b>Sair</b>, a janela volta no próximo acesso."},{"t":"nota","tipo":"dica","h":"mesmo sem essa exigência, você pode trocar a senha quando quiser em <b>Configurações</b>."}],"busca":"primeiros passos trocar a senha no primeiro acesso (quando o administrador exigir) a senha que o administrador cria ou gera para voce e definitiva: voce pode usa-la normalmente. so se ele marcar a opcao exigir que a pessoa troque a senha no primeiro acesso o painel nao deixa voce continuar sem criar uma senha so sua. entre com a senha que o administrador passou. na janela defina a sua senha, digite essa senha no primeiro campo (a que voce usou para entrar). digite a nova senha (minimo 6 caracteres) e repita em repita a nova senha. toque em salvar nova senha. a nova senha precisa ter pelo menos 6 caracteres e ser diferente da anterior. se voce tocar em sair, a janela volta no proximo acesso. mesmo sem essa exigencia, voce pode trocar a senha quando quiser em configuracoes."},{"id":"1-instalar-o-painel-como-aplicativo","titulo":"Instalar o painel como aplicativo","admin":false,"blocos":[{"t":"p","h":"O painel funciona como um aplicativo: abre em tela cheia, com ícone próprio, sem a barra do navegador."},{"t":"ol","itens":[{"h":"No menu lateral (veja o tópico seguinte), role até o rodapé e toque em <b>Instalar aplicativo</b>. O botão só aparece quando o aparelho permite instalar."},{"h":"<b>No Android (Chrome):</b> confirme a instalação na janela que o navegador mostra."},{"h":"<b>No iPhone (Safari):</b> aparece o aviso <b>Instalar no iPhone</b>. Toque em <b>Compartilhar</b> e depois em <b>Adicionar à Tela de Início</b>."},{"h":"Abra o ZapZap pelo novo ícone na tela inicial."}]},{"t":"nota","tipo":"dica","h":"o painel se atualiza sozinho. Quando sai uma versão nova, aparece o aviso <b>Atualizando…</b> por alguns segundos e a tela recarrega."}],"busca":"primeiros passos instalar o painel como aplicativo o painel funciona como um aplicativo: abre em tela cheia, com icone proprio, sem a barra do navegador. no menu lateral (veja o topico seguinte), role ate o rodape e toque em instalar aplicativo. o botao so aparece quando o aparelho permite instalar. no android (chrome): confirme a instalacao na janela que o navegador mostra. no iphone (safari): aparece o aviso instalar no iphone. toque em compartilhar e depois em adicionar a tela de inicio. abra o zapzap pelo novo icone na tela inicial. o painel se atualiza sozinho. quando sai uma versao nova, aparece o aviso atualizando… por alguns segundos e a tela recarrega."},{"id":"1-usar-o-menu-e-navegar","titulo":"Usar o menu e navegar","admin":false,"blocos":[{"t":"p","h":"No celular há uma barra de atalhos na parte de baixo e um menu lateral com todas as telas."},{"t":"ol","itens":[{"h":"Na barra de baixo estão as telas mais usadas: <b>Painel</b>, <b>Conversas</b>, o botão redondo <b>+</b> (que abre o <b>Enviar</b>), <b>Atendimento</b> e <b>Menu</b>."},{"h":"Toque em <b>Menu</b> (ou no botão de três riscos no canto superior esquerdo) para abrir a lista completa de telas.","img":"manual/img/menu.webp","alt":"Menu lateral aberto com todas as telas"},{"h":"Você também pode <b>deslizar o dedo da borda esquerda da tela para a direita</b> para abrir o menu, e deslizar para a esquerda para fechá-lo."},{"h":"No fim do menu ficam o seu nome, o botão <b>Sair</b> e a versão do painel."}]},{"t":"nota","tipo":"dica","h":"você só vê no menu as telas que o administrador liberou para o seu usuário. Se faltar alguma, peça a ele."},{"t":"nota","tipo":"aviso","h":"dentro de uma conversa aberta no celular o gesto de deslizar fica desligado, para não atrapalhar. Use o botão de voltar da conversa."}],"busca":"primeiros passos usar o menu e navegar no celular ha uma barra de atalhos na parte de baixo e um menu lateral com todas as telas. na barra de baixo estao as telas mais usadas: painel, conversas, o botao redondo + (que abre o enviar), atendimento e menu. toque em menu (ou no botao de tres riscos no canto superior esquerdo) para abrir a lista completa de telas. voce tambem pode deslizar o dedo da borda esquerda da tela para a direita para abrir o menu, e deslizar para a esquerda para fecha-lo. no fim do menu ficam o seu nome, o botao sair e a versao do painel. voce so ve no menu as telas que o administrador liberou para o seu usuario. se faltar alguma, peca a ele. dentro de uma conversa aberta no celular o gesto de deslizar fica desligado, para nao atrapalhar. use o botao de voltar da conversa."},{"id":"1-trocar-de-conexao-de-whatsapp","titulo":"Trocar de conexão (de WhatsApp)","admin":false,"blocos":[{"t":"p","h":"Um mesmo painel pode ter vários números de WhatsApp (cada um é uma &quot;conexão&quot;). Tudo o que você vê — conversas, contatos, agendadas — pertence à conexão ativa."},{"t":"ol","itens":[{"h":"No topo da tela, toque no botão com o nome da conexão e uma bolinha de cor (verde = conectada, vermelha = desconectada)."},{"h":"Na janela <b>Seus WhatsApps</b>, toque na conexão que deseja usar.","img":"manual/img/seletor-conexao.webp","alt":"Janela para escolher a conexão ativa"},{"h":"O painel recarrega a tela atual com os dados da nova conexão e mostra o aviso <b>Conexão: nome</b>."},{"h":"Para adicionar outro número, toque em <b>Conectar outro</b> (veja a seção 2)."}]}],"busca":"primeiros passos trocar de conexao (de whatsapp) um mesmo painel pode ter varios numeros de whatsapp (cada um e uma \"conexao\"). tudo o que voce ve — conversas, contatos, agendadas — pertence a conexao ativa. no topo da tela, toque no botao com o nome da conexao e uma bolinha de cor (verde = conectada, vermelha = desconectada). na janela seus whatsapps, toque na conexao que deseja usar. o painel recarrega a tela atual com os dados da nova conexao e mostra o aviso conexao: nome. para adicionar outro numero, toque em conectar outro (veja a secao 2)."},{"id":"1-central-de-notificacoes-sino","titulo":"Central de notificações (sino)","admin":false,"blocos":[{"t":"p","h":"O sino no topo avisa sobre mensagens novas, atendimentos, agendamentos, campanhas, conexão e automações."},{"t":"ol","itens":[{"h":"Quando há novidade, o sino mostra um número vermelho."},{"h":"Para mensagens que chegam enquanto você usa o painel, aparece um banner rápido no alto da tela. Toque nele para ir direto à conversa.","img":"manual/img/notificacao-banner.webp","alt":"Banner de notificação sobre uma mensagem nova"},{"h":"Toque no sino para abrir a central <b>Notificações</b>. Use as abas <b>Todas</b>, <b>Mensagens</b> e <b>Alertas</b> para filtrar.","img":"manual/img/notificacoes.webp","alt":"Central de notificações aberta"},{"h":"Toque em um aviso para ir à tela correspondente."},{"h":"Toque em <b>Marcar tudo como visto</b> para zerar o contador."}]}],"busca":"primeiros passos central de notificacoes (sino) o sino no topo avisa sobre mensagens novas, atendimentos, agendamentos, campanhas, conexao e automacoes. quando ha novidade, o sino mostra um numero vermelho. para mensagens que chegam enquanto voce usa o painel, aparece um banner rapido no alto da tela. toque nele para ir direto a conversa. toque no sino para abrir a central notificacoes. use as abas todas, mensagens e alertas para filtrar. toque em um aviso para ir a tela correspondente. toque em marcar tudo como visto para zerar o contador."},{"id":"1-preferencias-de-notificacao-som-vibracao-e-nao-perturbe","titulo":"Preferências de notificação: som, vibração e não perturbe","admin":false,"blocos":[{"t":"p","h":"Cada pessoa ajusta os avisos do seu próprio aparelho."},{"t":"ol","itens":[{"h":"Abra o sino e toque no botão de controles (<b>Preferências</b>) no canto superior direito."},{"h":"Ligue ou desligue <b>Efeito sonoro</b>, ajuste o <b>Volume</b> e escolha o tom: <b>Sino</b>, <b>Gota</b>, <b>Suave</b>, <b>Pulso</b> ou <b>Alerta</b> (toque para ouvir)."},{"h":"Ligue <b>Vibração (celulares compatíveis)</b> se quiser que o aparelho vibre."},{"h":"Ligue <b>Notificação do navegador (com a aba em segundo plano)</b> para receber avisos mesmo com o painel em outra aba. O navegador pede a sua permissão."},{"h":"Ligue <b>Não perturbe</b> e escolha o horário (<b>Das</b> ... <b>até</b>) em que os avisos devem ficar quietos."},{"h":"Em <b>Avisar sobre</b>, marque só os tipos que importam para você."},{"h":"Toque em <b>Testar</b> para simular um aviso e em <b>Pronto</b> para fechar.","img":"manual/img/notificacoes-preferencias.webp","alt":"Preferências de notificação"}]},{"t":"nota","tipo":"dica","h":"no iPhone o navegador não libera a vibração, e o som segue a chave de silencioso do aparelho."}],"busca":"primeiros passos preferencias de notificacao: som, vibracao e nao perturbe cada pessoa ajusta os avisos do seu proprio aparelho. abra o sino e toque no botao de controles (preferencias) no canto superior direito. ligue ou desligue efeito sonoro, ajuste o volume e escolha o tom: sino, gota, suave, pulso ou alerta (toque para ouvir). ligue vibracao (celulares compativeis) se quiser que o aparelho vibre. ligue notificacao do navegador (com a aba em segundo plano) para receber avisos mesmo com o painel em outra aba. o navegador pede a sua permissao. ligue nao perturbe e escolha o horario (das ... ate) em que os avisos devem ficar quietos. em avisar sobre, marque so os tipos que importam para voce. toque em testar para simular um aviso e em pronto para fechar. no iphone o navegador nao libera a vibracao, e o som segue a chave de silencioso do aparelho."},{"id":"1-conhecer-o-painel-pagina-inicial","titulo":"Conhecer o Painel (página inicial)","admin":false,"blocos":[{"t":"p","h":"O Painel mostra, de relance, como está o dia da conexão ativa."},{"t":"ol","itens":[{"h":"No alto, o cartão do perfil mostra a foto, o nome, o número e o selo <b>Conectado</b> (ou <b>Desconectado</b>)."},{"h":"Os quatro cartões mostram <b>Enviadas hoje</b>, <b>Recebidas hoje</b>, <b>Agendadas pendentes</b> e <b>Envios do painel</b> (com quantos deram certo e quantos deram erro)."},{"h":"O gráfico <b>Últimos 7 dias</b> compara mensagens enviadas (azul) e recebidas (verde); logo abaixo há a tabela com os mesmos números."},{"h":"Em <b>Atividade recente</b> toque numa linha para abrir a conversa."},{"h":"Os atalhos <b>Enviar mensagem</b>, <b>Conversas</b> e <b>Agendar</b> levam direto às telas."}]},{"t":"nota","tipo":"dica","h":"o selo <b>ao vivo</b> indica que a tela se atualiza sozinha, a cada poucos segundos."},{"t":"img","src":"manual/img/painel-desktop.webp","alt":"Painel no computador"}],"busca":"primeiros passos conhecer o painel (pagina inicial) o painel mostra, de relance, como esta o dia da conexao ativa. no alto, o cartao do perfil mostra a foto, o nome, o numero e o selo conectado (ou desconectado). os quatro cartoes mostram enviadas hoje, recebidas hoje, agendadas pendentes e envios do painel (com quantos deram certo e quantos deram erro). o grafico ultimos 7 dias compara mensagens enviadas (azul) e recebidas (verde); logo abaixo ha a tabela com os mesmos numeros. em atividade recente toque numa linha para abrir a conversa. os atalhos enviar mensagem, conversas e agendar levam direto as telas. o selo ao vivo indica que a tela se atualiza sozinha, a cada poucos segundos. "}]},{"n":2,"titulo":"Conectar um WhatsApp","topicos":[{"id":"2-ver-as-conexoes","titulo":"Ver as conexões","admin":false,"blocos":[{"t":"p","h":"A tela <b>Conexões</b> lista cada número ligado ao painel e permite conectar, sincronizar, renomear, desconectar e excluir."},{"t":"ol","itens":[{"h":"Abra <b>Conexões</b> no menu."},{"h":"Cada cartão mostra a foto, o apelido, o número, o estado (<b>Conectado</b>, <b>Conectando</b> ou <b>Desconectado</b>) e quantas mensagens, contatos e conversas existem.","img":"manual/img/conexoes.webp","alt":"Lista de conexões do painel"},{"h":"A conexão em uso tem o selo <b>Ativa</b>. Em outra conexão, toque em <b>Usar esta</b> para torná-la ativa."},{"h":"Toque em <b>Renomear</b> para mudar o apelido (até 40 caracteres), por exemplo &quot;Loja Aurora&quot;."}]},{"t":"nota","tipo":"dica","h":"conexões com o cadeado são <b>protegidas</b>: o painel não permite desconectá-las nem excluí-las."}],"busca":"conectar um whatsapp ver as conexoes a tela conexoes lista cada numero ligado ao painel e permite conectar, sincronizar, renomear, desconectar e excluir. abra conexoes no menu. cada cartao mostra a foto, o apelido, o numero, o estado (conectado, conectando ou desconectado) e quantas mensagens, contatos e conversas existem. a conexao em uso tem o selo ativa. em outra conexao, toque em usar esta para torna-la ativa. toque em renomear para mudar o apelido (ate 40 caracteres), por exemplo \"loja aurora\". conexoes com o cadeado sao protegidas: o painel nao permite desconecta-las nem exclui-las."},{"id":"2-conectar-um-novo-numero","titulo":"Conectar um novo número","admin":true,"blocos":[{"t":"p","h":"Para cada número novo, crie uma conexão e leia um QR Code com o celular."},{"t":"ol","itens":[{"h":"Em <b>Conexões</b>, toque em <b>Conectar novo WhatsApp</b>."},{"h":"Preencha o <b>Apelido</b> (por exemplo, &quot;WhatsApp da loja&quot;). O <b>Nome técnico</b> é sugerido automaticamente e aceita só letras, números, &quot;-&quot; e &quot;_&quot; (2 a 40 caracteres)."},{"h":"Toque em <b>Criar</b>. O painel avisa <b>Conexão criada. Leia o QR Code.</b> e abre a tela de leitura.","img":"manual/img/conexao-nova.webp","alt":"Janela para criar uma nova conexão"}]}],"busca":"conectar um whatsapp conectar um novo numero para cada numero novo, crie uma conexao e leia um qr code com o celular. em conexoes, toque em conectar novo whatsapp. preencha o apelido (por exemplo, \"whatsapp da loja\"). o nome tecnico e sugerido automaticamente e aceita so letras, numeros, \"-\" e \"_\" (2 a 40 caracteres). toque em criar. o painel avisa conexao criada. leia o qr code. e abre a tela de leitura."},{"id":"2-conectar-lendo-o-qr-code","titulo":"Conectar lendo o QR Code","admin":true,"blocos":[{"t":"p","h":"O QR Code liga o painel ao WhatsApp do seu celular, do mesmo jeito que o WhatsApp Web."},{"t":"ol","itens":[{"h":"Em um cartão desconectado, toque em <b>Conectar / Gerar QR</b>."},{"h":"No celular, abra o <b>WhatsApp</b>, vá em <b>Configurações</b>, <b>Aparelhos conectados</b> e <b>Conectar um aparelho</b>."},{"h":"Aponte a câmera para o QR Code da tela do painel.","img":"manual/img/conexao-qr.webp","alt":"QR Code para conectar o WhatsApp"},{"h":"A tela mostra <b>Aguardando a leitura…</b> e atualiza sozinha. Quando conecta, aparece <b>Conectado!</b> com uma animação de confirmação."},{"h":"Toque em <b>Usar esta conexão</b> para trabalhar com ela agora, ou em <b>Fechar</b>."}]},{"t":"nota","tipo":"dica","h":"o QR Code vale por cerca de 25 segundos; uma barra mostra o tempo e um novo código é gerado automaticamente. Se der erro, toque em <b>Tentar de novo</b>."}],"busca":"conectar um whatsapp conectar lendo o qr code o qr code liga o painel ao whatsapp do seu celular, do mesmo jeito que o whatsapp web. em um cartao desconectado, toque em conectar / gerar qr. no celular, abra o whatsapp, va em configuracoes, aparelhos conectados e conectar um aparelho. aponte a camera para o qr code da tela do painel. a tela mostra aguardando a leitura… e atualiza sozinha. quando conecta, aparece conectado! com uma animacao de confirmacao. toque em usar esta conexao para trabalhar com ela agora, ou em fechar. o qr code vale por cerca de 25 segundos; uma barra mostra o tempo e um novo codigo e gerado automaticamente. se der erro, toque em tentar de novo."},{"id":"2-conectar-com-codigo-de-pareamento","titulo":"Conectar com código de pareamento","admin":true,"blocos":[{"t":"p","h":"Se você não consegue apontar a câmera (por exemplo, está no mesmo celular), use o código."},{"t":"ol","itens":[{"h":"Na tela do QR, toque na aba <b>Por código</b>."},{"h":"Digite o número do WhatsApp com DDI e DDD (exemplo: 5582999990001) e toque em <b>Gerar código</b>."},{"h":"No WhatsApp do celular, vá em <b>Aparelhos conectados</b>, <b>Conectar um aparelho</b> e escolha <b>Conectar com número de telefone</b>."},{"h":"Digite o código de oito caracteres mostrado na tela do painel.","img":"manual/img/conexao-codigo.webp","alt":"Código de pareamento no painel"}]}],"busca":"conectar um whatsapp conectar com codigo de pareamento se voce nao consegue apontar a camera (por exemplo, esta no mesmo celular), use o codigo. na tela do qr, toque na aba por codigo. digite o numero do whatsapp com ddi e ddd (exemplo: 5582999990001) e toque em gerar codigo. no whatsapp do celular, va em aparelhos conectados, conectar um aparelho e escolha conectar com numero de telefone. digite o codigo de oito caracteres mostrado na tela do painel."},{"id":"2-sincronizacao-completa-dos-dados","titulo":"Sincronização completa dos dados","admin":true,"blocos":[{"t":"p","h":"Ao conectar, o painel baixa os dados do número para mostrar contatos, grupos e histórico."},{"t":"ol","itens":[{"h":"Logo após conectar, a janela <b>Baixando seus dados…</b> mostra as etapas: <b>Perfil e recado</b>, <b>Contatos e fotos</b>, <b>Grupos</b>, <b>Conversas</b>, <b>Histórico de mensagens</b> e <b>Mídias</b>, com barra de progresso.","img":"manual/img/conexao-sincronizando.webp","alt":"Sincronização em andamento"},{"h":"No fim aparece o resumo com a quantidade de contatos, grupos, conversas e mensagens."},{"h":"Se quiser, escolha <b>últimos 7 dias</b>, <b>15 dias</b> ou <b>30 dias</b> e toque em <b>Baixar também as mídias</b> para trazer fotos, vídeos, áudios e documentos recentes (até 500 MB, em segundo plano). Dá para tocar em <b>Cancelar download</b>."},{"h":"Em qualquer momento, com a conexão ativa, toque em <b>Sincronizar agora</b> no cartão para repetir o processo."}]}],"busca":"conectar um whatsapp sincronizacao completa dos dados ao conectar, o painel baixa os dados do numero para mostrar contatos, grupos e historico. logo apos conectar, a janela baixando seus dados… mostra as etapas: perfil e recado, contatos e fotos, grupos, conversas, historico de mensagens e midias, com barra de progresso. no fim aparece o resumo com a quantidade de contatos, grupos, conversas e mensagens. se quiser, escolha ultimos 7 dias, 15 dias ou 30 dias e toque em baixar tambem as midias para trazer fotos, videos, audios e documentos recentes (ate 500 mb, em segundo plano). da para tocar em cancelar download. em qualquer momento, com a conexao ativa, toque em sincronizar agora no cartao para repetir o processo."},{"id":"2-desconectar-ocultar-ou-apagar-os-dados","titulo":"Desconectar, ocultar ou apagar os dados","admin":true,"blocos":[{"t":"p","h":"Ao desconectar (ou limpar) um número, você decide o que acontece com os dados dele no painel."},{"t":"ol","itens":[{"h":"No cartão da conexão, toque em <b>Desconectar</b> (se estiver conectada) ou <b>Limpar dados</b> (se já estiver desconectada)."},{"h":"Escolha uma das opções:<br>- <b>Manter dados:</b> só desconecta o WhatsApp; mensagens, contatos e grupos continuam aparecendo.<br>- <b>Ocultar dados (recomendado para trocar de número):</b> o painel passa a mostrar só o que chegar depois, nada é apagado do servidor.<br>- <b>Apagar tudo:</b> apaga mensagens, contatos e registros da conexão e a recria zerada; não dá para desfazer. Para liberar, digite o nome técnico da conexão.","img":"manual/img/conexao-desconectar.webp","alt":"Opções ao desconectar uma conexão"},{"h":"Confirme no aviso que aparece."},{"h":"Se escolheu <b>Ocultar dados</b>, o cartão mostra <b>Dados ocultos</b> e o botão <b>Mostrar dados de novo</b> desfaz a ocultação."}]},{"t":"nota","tipo":"aviso","h":"<b>Apagar tudo</b> é irreversível. Prefira <b>Ocultar dados</b> quando estiver só trocando de número."}],"busca":"conectar um whatsapp desconectar, ocultar ou apagar os dados ao desconectar (ou limpar) um numero, voce decide o que acontece com os dados dele no painel. no cartao da conexao, toque em desconectar (se estiver conectada) ou limpar dados (se ja estiver desconectada). escolha uma das opcoes:- manter dados: so desconecta o whatsapp; mensagens, contatos e grupos continuam aparecendo.- ocultar dados (recomendado para trocar de numero): o painel passa a mostrar so o que chegar depois, nada e apagado do servidor.- apagar tudo: apaga mensagens, contatos e registros da conexao e a recria zerada; nao da para desfazer. para liberar, digite o nome tecnico da conexao. confirme no aviso que aparece. se escolheu ocultar dados, o cartao mostra dados ocultos e o botao mostrar dados de novo desfaz a ocultacao. apagar tudo e irreversivel. prefira ocultar dados quando estiver so trocando de numero."},{"id":"2-excluir-uma-conexao","titulo":"Excluir uma conexão","admin":true,"blocos":[{"t":"ol","itens":[{"h":"No cartão da conexão, toque em <b>Excluir</b>."},{"h":"Leia o aviso e digite o nome da conexão para confirmar."},{"h":"Toque no botão vermelho para concluir. O painel mostra <b>Conexão excluída</b>."}]},{"t":"nota","tipo":"aviso","h":"a exclusão é definitiva e não está disponível para conexões protegidas (com cadeado)."}],"busca":"conectar um whatsapp excluir uma conexao no cartao da conexao, toque em excluir. leia o aviso e digite o nome da conexao para confirmar. toque no botao vermelho para concluir. o painel mostra conexao excluida. a exclusao e definitiva e nao esta disponivel para conexoes protegidas (com cadeado)."},{"id":"2-aviso-por-e-mail-quando-a-conexao-cai","titulo":"Aviso por e-mail quando a conexão cai","admin":false,"blocos":[{"t":"p","h":"O painel confere o estado de todas as conexões a cada minuto. Quando uma cai (ou volta a funcionar), ele manda um e-mail de aviso ao responsável técnico e registra uma notificação na central (sino)."},{"t":"ol","itens":[{"h":"Se aparecer <b>Desconectado</b> no topo ou no cartão, abra <b>Conexões</b>."},{"h":"Toque em <b>Conectar / Gerar QR</b> e leia o código de novo."},{"h":"Quando voltar, o painel avisa que a conexão foi restabelecida."}]},{"t":"nota","tipo":"dica","h":"para evitar repetição, o aviso por e-mail não é reenviado para a mesma conexão em menos de 30 minutos."}],"busca":"conectar um whatsapp aviso por e-mail quando a conexao cai o painel confere o estado de todas as conexoes a cada minuto. quando uma cai (ou volta a funcionar), ele manda um e-mail de aviso ao responsavel tecnico e registra uma notificacao na central (sino). se aparecer desconectado no topo ou no cartao, abra conexoes. toque em conectar / gerar qr e leia o codigo de novo. quando voltar, o painel avisa que a conexao foi restabelecida. para evitar repeticao, o aviso por e-mail nao e reenviado para a mesma conexao em menos de 30 minutos."}]},{"n":3,"titulo":"Conversas","topicos":[{"id":"3-ver-a-lista-de-conversas","titulo":"Ver a lista de conversas","admin":false,"blocos":[{"t":"p","h":"A tela <b>Conversas</b> mostra todas as conversas da conexão ativa, da mais recente para a mais antiga."},{"t":"ol","itens":[{"h":"Abra <b>Conversas</b> na barra de baixo."},{"h":"Cada linha mostra a foto (ou as iniciais), o nome, a prévia da última mensagem, a hora e um contador de mensagens não lidas."},{"h":"Use o campo <b>Buscar conversa ou número</b> para filtrar."},{"h":"Quando alguém está digitando ou gravando áudio, a prévia mostra &quot;digitando…&quot; ou &quot;gravando áudio&quot;.","img":"manual/img/conversas.webp","alt":"Lista de conversas no celular"},{"h":"Toque numa conversa para abri-la. No computador, a lista fica à esquerda e a conversa à direita.","img":"manual/img/conversas-desktop.webp","alt":"Conversas no computador"}]},{"t":"nota","tipo":"dica","h":"o selo <b>ao vivo</b> mostra que a lista se atualiza sozinha."}],"busca":"conversas ver a lista de conversas a tela conversas mostra todas as conversas da conexao ativa, da mais recente para a mais antiga. abra conversas na barra de baixo. cada linha mostra a foto (ou as iniciais), o nome, a previa da ultima mensagem, a hora e um contador de mensagens nao lidas. use o campo buscar conversa ou numero para filtrar. quando alguem esta digitando ou gravando audio, a previa mostra \"digitando…\" ou \"gravando audio\". toque numa conversa para abri-la. no computador, a lista fica a esquerda e a conversa a direita. o selo ao vivo mostra que a lista se atualiza sozinha."},{"id":"3-ler-e-responder-mensagens","titulo":"Ler e responder mensagens","admin":false,"blocos":[{"t":"p","h":"Dentro da conversa, as mensagens aparecem em ordem, com a marca de entrega."},{"t":"ol","itens":[{"h":"Role para cima e toque em <b>Carregar mais</b> para ver mensagens antigas."},{"h":"Quando chegarem mensagens novas e você estiver lendo o histórico, aparece o botão <b>Novas mensagens</b>; toque nele para descer."},{"h":"Digite no campo <b>Digite uma mensagem</b> e toque no botão de avião de papel para enviar."},{"h":"Acompanhe a marca de cada mensagem: enviando, enviada, entregue, lida (azul) ou falhou — nas que falharem há a opção de reenviar.","img":"manual/img/conversa.webp","alt":"Conversa aberta com mensagens"}]},{"t":"nota","tipo":"aviso","h":"o limite de uma mensagem é de 4096 caracteres."}],"busca":"conversas ler e responder mensagens dentro da conversa, as mensagens aparecem em ordem, com a marca de entrega. role para cima e toque em carregar mais para ver mensagens antigas. quando chegarem mensagens novas e voce estiver lendo o historico, aparece o botao novas mensagens; toque nele para descer. digite no campo digite uma mensagem e toque no botao de aviao de papel para enviar. acompanhe a marca de cada mensagem: enviando, enviada, entregue, lida (azul) ou falhou — nas que falharem ha a opcao de reenviar. o limite de uma mensagem e de 4096 caracteres."},{"id":"3-respostas-assinadas","titulo":"Respostas assinadas","admin":false,"blocos":[{"t":"p","h":"Toda mensagem enviada por um usuário sai com o nome dele, para o cliente saber quem está falando."},{"t":"ol","itens":[{"h":"Acima do campo de mensagem aparece a linha <b>Sai assinada como</b> seguida do seu nome entre asteriscos e dois pontos."},{"h":"Escreva normalmente: o painel acrescenta a assinatura na primeira linha."},{"h":"A assinatura vale também para legendas de mídia, enquetes, localização e mensagens agendadas."}]},{"t":"nota","tipo":"aviso","h":"não existe opção para desligar a assinatura. Mensagens automáticas (automações e chatbot) não levam assinatura."}],"busca":"conversas respostas assinadas toda mensagem enviada por um usuario sai com o nome dele, para o cliente saber quem esta falando. acima do campo de mensagem aparece a linha sai assinada como seguida do seu nome entre asteriscos e dois pontos. escreva normalmente: o painel acrescenta a assinatura na primeira linha. a assinatura vale tambem para legendas de midia, enquetes, localizacao e mensagens agendadas. nao existe opcao para desligar a assinatura. mensagens automaticas (automacoes e chatbot) nao levam assinatura."},{"id":"3-enviar-fotos-documentos-e-outros-arquivos","titulo":"Enviar fotos, documentos e outros arquivos","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Toque no clipe (<b>Anexar arquivo</b>) ao lado do campo de mensagem."},{"h":"Escolha uma imagem, vídeo, áudio, PDF, Word, Excel, TXT ou ZIP de até 25 MB."},{"h":"Aparece uma pré-visualização do arquivo. Digite uma <b>Legenda (opcional)</b> no campo de texto."},{"h":"Toque no avião de papel para enviar. Para desistir, toque no X da pré-visualização."}]},{"t":"nota","tipo":"dica","h":"se o arquivo passar de 25 MB o painel avisa <b>Arquivo muito grande (máximo 25 MB)</b>."}],"busca":"conversas enviar fotos, documentos e outros arquivos toque no clipe (anexar arquivo) ao lado do campo de mensagem. escolha uma imagem, video, audio, pdf, word, excel, txt ou zip de ate 25 mb. aparece uma pre-visualizacao do arquivo. digite uma legenda (opcional) no campo de texto. toque no aviao de papel para enviar. para desistir, toque no x da pre-visualizacao. se o arquivo passar de 25 mb o painel avisa arquivo muito grande (maximo 25 mb)."},{"id":"3-gravar-e-enviar-audio","titulo":"Gravar e enviar áudio","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Com o campo de texto vazio, toque no microfone (<b>Gravar áudio</b>)."},{"h":"Permita o uso do microfone se o navegador pedir. A tela mostra o cronômetro e uma animação; a gravação vai até 5 minutos."},{"h":"Toque no botão de enviar para parar a gravação. Aparece um player para você ouvir antes de decidir."},{"h":"Toque em enviar para mandar o áudio, ou na lixeira (<b>Descartar áudio</b>) para jogar fora."}]},{"t":"nota","tipo":"dica","h":"enquanto você grava, o contato vê &quot;gravando áudio&quot; no WhatsApp dele; enquanto você digita, ele vê &quot;digitando…&quot;."}],"busca":"conversas gravar e enviar audio com o campo de texto vazio, toque no microfone (gravar audio). permita o uso do microfone se o navegador pedir. a tela mostra o cronometro e uma animacao; a gravacao vai ate 5 minutos. toque no botao de enviar para parar a gravacao. aparece um player para voce ouvir antes de decidir. toque em enviar para mandar o audio, ou na lixeira (descartar audio) para jogar fora. enquanto voce grava, o contato ve \"gravando audio\" no whatsapp dele; enquanto voce digita, ele ve \"digitando…\"."},{"id":"3-marcar-como-lida","titulo":"Marcar como lida","admin":false,"blocos":[{"t":"p","h":"O painel nunca avisa o contato de leitura sem você querer: a marcação como lida é uma escolha sua."},{"t":"ol","itens":[{"h":"Na conversa, toque em <b>Marcar como lida</b> (botão com dois tiques no topo; no celular fica no menu de três pontos)."},{"h":"O painel avisa <b>Conversa marcada como lida</b>."},{"h":"No menu de três pontos há ainda o interruptor <b>Marcar como lida ao abrir</b>: ligado, toda conversa que você abrir é marcada como lida automaticamente."}]}],"busca":"conversas marcar como lida o painel nunca avisa o contato de leitura sem voce querer: a marcacao como lida e uma escolha sua. na conversa, toque em marcar como lida (botao com dois tiques no topo; no celular fica no menu de tres pontos). o painel avisa conversa marcada como lida. no menu de tres pontos ha ainda o interruptor marcar como lida ao abrir: ligado, toda conversa que voce abrir e marcada como lida automaticamente."},{"id":"3-respostas-rapidas-com-a-barra","titulo":"Respostas rápidas com a barra \"/\"","admin":false,"blocos":[{"t":"p","h":"Respostas rápidas são textos prontos que você chama por um atalho (veja a seção Respostas rápidas na tela do mesmo nome)."},{"t":"ol","itens":[{"h":"No campo de mensagem, digite <b>/</b> seguido do atalho (por exemplo, <b>/horario</b>). Aparecem sugestões com o atalho e o texto."},{"h":"Toque numa sugestão para colocar o texto no campo; revise e envie."},{"h":"Ou toque no raio (<b>Respostas rápidas</b>) ao lado do clipe para abrir a lista completa e escolher uma resposta.","img":"manual/img/conversa-respostas.webp","alt":"Sugestões de respostas rápidas ao digitar a barra"}]},{"t":"nota","tipo":"dica","h":"os textos aceitam variáveis como <b>{nome}</b>, <b>{numero}</b>, <b>{saudacao}</b> e <b>{atendente}</b>, que o painel troca pelos dados reais."}],"busca":"conversas respostas rapidas com a barra \"/\" respostas rapidas sao textos prontos que voce chama por um atalho (veja a secao respostas rapidas na tela do mesmo nome). no campo de mensagem, digite / seguido do atalho (por exemplo, /horario). aparecem sugestoes com o atalho e o texto. toque numa sugestao para colocar o texto no campo; revise e envie. ou toque no raio (respostas rapidas) ao lado do clipe para abrir a lista completa e escolher uma resposta. os textos aceitam variaveis como {nome}, {numero}, {saudacao} e {atendente}, que o painel troca pelos dados reais."},{"id":"3-etiquetas-na-conversa","titulo":"Etiquetas na conversa","admin":true,"blocos":[{"t":"p","h":"Etiquetas são rótulos coloridos para organizar contatos (por exemplo, &quot;Cliente&quot;, &quot;Orçamento&quot;)."},{"t":"ol","itens":[{"h":"No cabeçalho da conversa, toque em <b>Etiquetas</b>."},{"h":"Toque nas etiquetas que deseja aplicar ou retirar; as marcadas ficam destacadas e a janela mostra quantas estão marcadas."},{"h":"Para criar uma etiqueta nova na hora, digite o nome em <b>Nova etiqueta…</b>, escolha uma cor e toque em <b>Criar</b> (ela já é aplicada à conversa)."},{"h":"Toque em <b>Pronto</b>. As etiquetas aparecem como chips no cabeçalho.","img":"manual/img/conversa-etiquetas.webp","alt":"Seletor de etiquetas da conversa"}]}],"busca":"conversas etiquetas na conversa etiquetas sao rotulos coloridos para organizar contatos (por exemplo, \"cliente\", \"orcamento\"). no cabecalho da conversa, toque em etiquetas. toque nas etiquetas que deseja aplicar ou retirar; as marcadas ficam destacadas e a janela mostra quantas estao marcadas. para criar uma etiqueta nova na hora, digite o nome em nova etiqueta…, escolha uma cor e toque em criar (ela ja e aplicada a conversa). toque em pronto. as etiquetas aparecem como chips no cabecalho."},{"id":"3-notas-internas","titulo":"Notas internas","admin":false,"blocos":[{"t":"p","h":"Notas são anotações só da equipe: nunca vão para o cliente."},{"t":"ol","itens":[{"h":"No cabeçalho da conversa, toque em <b>Notas</b>."},{"h":"Escreva no campo <b>Escreva uma nota interna…</b> (até 2000 caracteres) e toque em <b>Adicionar nota</b>."},{"h":"Use o alfinete para fixar uma nota importante no topo e a lixeira para excluir.","img":"manual/img/conversa-notas.webp","alt":"Notas internas da conversa"}]}],"busca":"conversas notas internas notas sao anotacoes so da equipe: nunca vao para o cliente. no cabecalho da conversa, toque em notas. escreva no campo escreva uma nota interna… (ate 2000 caracteres) e toque em adicionar nota. use o alfinete para fixar uma nota importante no topo e a lixeira para excluir."},{"id":"3-lembrar-de-responder","titulo":"Lembrar de responder","admin":false,"blocos":[{"t":"p","h":"A tela <b>Lembretes</b> reúne os avisos &quot;me lembre de responder&quot;. Cada lembrete avisa você, com som e vibração, se a conversa ainda não foi respondida."},{"t":"ol","itens":[{"h":"Abra <b>Lembretes</b> no menu."},{"h":"Use as abas <b>Pendentes</b>, <b>Avisados</b>, <b>Respondidos</b> e <b>Cancelados</b>.","img":"manual/img/lembretes.webp","alt":"Tela de lembretes"},{"h":"Em cada lembrete, toque no balão para abrir a conversa, na ampulheta para <b>Adiar 1 hora</b>, no visto para marcar <b>Já respondi</b> ou no X para cancelar."},{"h":"Ao criar um lembrete você escolhe 15 min, 30 min, 1 hora, 2 horas, 4 horas, Hoje 18h, Amanhã 9h ou uma data e hora com <b>Escolher…</b>, e pode incluir uma anotação."}]},{"t":"nota","tipo":"aviso","h":"nesta versão a tela <b>Lembretes</b> e a janela <b>Me lembrar de responder</b> existem, mas não há um botão dentro da conversa que abra a janela de criação."}],"busca":"conversas lembrar de responder a tela lembretes reune os avisos \"me lembre de responder\". cada lembrete avisa voce, com som e vibracao, se a conversa ainda nao foi respondida. abra lembretes no menu. use as abas pendentes, avisados, respondidos e cancelados. em cada lembrete, toque no balao para abrir a conversa, na ampulheta para adiar 1 hora, no visto para marcar ja respondi ou no x para cancelar. ao criar um lembrete voce escolhe 15 min, 30 min, 1 hora, 2 horas, 4 horas, hoje 18h, amanha 9h ou uma data e hora com escolher…, e pode incluir uma anotacao. nesta versao a tela lembretes e a janela me lembrar de responder existem, mas nao ha um botao dentro da conversa que abra a janela de criacao."},{"id":"3-enviar-para-outro-numero","titulo":"Enviar para outro número","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Dentro da conversa, toque em <b>Enviar para outro número</b> (ou no menu de três pontos)."},{"h":"Você vai para a tela <b>Enviar</b> (seção 5) para escolher o destinatário."}]}],"busca":"conversas enviar para outro numero dentro da conversa, toque em enviar para outro numero (ou no menu de tres pontos). voce vai para a tela enviar (secao 5) para escolher o destinatario."}]},{"n":4,"titulo":"Atendimento e filas","topicos":[{"id":"4-entender-a-tela-atendimento","titulo":"Entender a tela Atendimento","admin":false,"blocos":[{"t":"p","h":"Atendimento organiza os clientes que escreveram em uma fila de espera, para que a equipe saiba quem já foi atendido e quem está esperando."},{"t":"ol","itens":[{"h":"Abra <b>Atendimento</b> na barra de baixo."},{"h":"As três abas mostram a contagem de cada situação: <b>Aguardando</b>, <b>Em atendimento</b> e <b>Resolvidos</b>. Toque para trocar."},{"h":"As pílulas <b>Todas</b> e os nomes das filas filtram por fila."},{"h":"O botão <b>Meus</b> mostra só os atendimentos que são seus; o sino liga e desliga o som de novo atendimento; <b>Novo</b> cria um atendimento; <b>Filas</b> abre a gestão das filas."},{"h":"Cada cartão mostra o contato, a prévia da última mensagem, a fila, quem atende e há quanto tempo o cliente está sem resposta.","img":"manual/img/atendimento.webp","alt":"Lista de atendimentos no celular"}]},{"t":"nota","tipo":"dica","h":"no computador a tela fica mais larga, com os cartões lado a lado."},{"t":"img","src":"manual/img/atendimento-desktop.webp","alt":"Atendimento no computador"}],"busca":"atendimento e filas entender a tela atendimento atendimento organiza os clientes que escreveram em uma fila de espera, para que a equipe saiba quem ja foi atendido e quem esta esperando. abra atendimento na barra de baixo. as tres abas mostram a contagem de cada situacao: aguardando, em atendimento e resolvidos. toque para trocar. as pilulas todas e os nomes das filas filtram por fila. o botao meus mostra so os atendimentos que sao seus; o sino liga e desliga o som de novo atendimento; novo cria um atendimento; filas abre a gestao das filas. cada cartao mostra o contato, a previa da ultima mensagem, a fila, quem atende e ha quanto tempo o cliente esta sem resposta. no computador a tela fica mais larga, com os cartoes lado a lado. "},{"id":"4-cores-de-espera-sla","titulo":"Cores de espera (SLA)","admin":false,"blocos":[{"t":"p","h":"O tempo sem resposta ganha cor para mostrar a urgência."},{"t":"ol","itens":[{"h":"<b>No prazo</b> (verde): o cliente espera pouco."},{"h":"<b>Atenção</b> (amarelo): a espera está crescendo."},{"h":"<b>Urgente</b> (laranja): é hora de responder."},{"h":"<b>Atrasado</b> (vermelho): passou de todos os limites e o cartão pulsa."},{"h":"Toque em uma cor da legenda para ver só aquele grupo. <b>Urgentes primeiro</b> coloca na frente quem espera há mais tempo."},{"h":"Os limites padrão são 5, 15 e 30 minutos; cada fila pode ter os seus.","img":"manual/img/atendimento-detalhe.webp","alt":"Detalhe de um atendimento com as cores de espera"}]}],"busca":"atendimento e filas cores de espera (sla) o tempo sem resposta ganha cor para mostrar a urgencia. no prazo (verde): o cliente espera pouco. atencao (amarelo): a espera esta crescendo. urgente (laranja): e hora de responder. atrasado (vermelho): passou de todos os limites e o cartao pulsa. toque em uma cor da legenda para ver so aquele grupo. urgentes primeiro coloca na frente quem espera ha mais tempo. os limites padrao sao 5, 15 e 30 minutos; cada fila pode ter os seus."},{"id":"4-assumir-um-atendimento","titulo":"Assumir um atendimento","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Em <b>Aguardando</b>, toque no cartão para abrir o detalhe."},{"h":"Toque em <b>Assumir</b>. O painel avisa <b>Você assumiu o atendimento</b> e ele passa para <b>Em atendimento</b>, no seu nome."},{"h":"Toque em <b>Abrir conversa</b> para responder ao cliente. As respostas saem assinadas com o seu nome."},{"h":"Dentro da própria conversa também aparecem os botões <b>Assumir</b>, <b>Transferir</b> e <b>Encerrar</b> quando o contato tem atendimento aberto."}]},{"t":"nota","tipo":"dica","h":"se outro atendente assumir primeiro, o painel avisa <b>Já assumido por</b> e atualiza a lista."}],"busca":"atendimento e filas assumir um atendimento em aguardando, toque no cartao para abrir o detalhe. toque em assumir. o painel avisa voce assumiu o atendimento e ele passa para em atendimento, no seu nome. toque em abrir conversa para responder ao cliente. as respostas saem assinadas com o seu nome. dentro da propria conversa tambem aparecem os botoes assumir, transferir e encerrar quando o contato tem atendimento aberto. se outro atendente assumir primeiro, o painel avisa ja assumido por e atualiza a lista."},{"id":"4-transferir-um-atendimento","titulo":"Transferir um atendimento","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No detalhe do atendimento (ou na conversa), toque em <b>Transferir</b>."},{"h":"Escolha <b>Para a fila</b> e/ou <b>Para o atendente</b>. Se deixar o atendente em branco, o atendimento volta para a fila sem dono."},{"h":"Escreva o <b>Motivo (opcional)</b>."},{"h":"Toque em <b>Transferir</b>. O painel avisa <b>Atendimento transferido</b>.","img":"manual/img/atendimento-transferir.webp","alt":"Janela para transferir um atendimento"}]}],"busca":"atendimento e filas transferir um atendimento no detalhe do atendimento (ou na conversa), toque em transferir. escolha para a fila e/ou para o atendente. se deixar o atendente em branco, o atendimento volta para a fila sem dono. escreva o motivo (opcional). toque em transferir. o painel avisa atendimento transferido."},{"id":"4-encerrar-e-reabrir","titulo":"Encerrar e reabrir","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No detalhe do atendimento, toque em <b>Encerrar</b>."},{"h":"Escreva um <b>Resumo do atendimento</b> (opcional) e confirme."},{"h":"O atendimento vai para <b>Resolvidos</b>, com o resumo no detalhe."},{"h":"Para voltar atrás, abra o atendimento resolvido e toque em <b>Reabrir</b>."},{"h":"A <b>Linha do tempo</b> no detalhe registra tudo: criação, quem assumiu, transferências, encerramento e o tempo de resposta de cada etapa."}]}],"busca":"atendimento e filas encerrar e reabrir no detalhe do atendimento, toque em encerrar. escreva um resumo do atendimento (opcional) e confirme. o atendimento vai para resolvidos, com o resumo no detalhe. para voltar atras, abra o atendimento resolvido e toque em reabrir. a linha do tempo no detalhe registra tudo: criacao, quem assumiu, transferencias, encerramento e o tempo de resposta de cada etapa."},{"id":"4-criar-um-atendimento-manualmente","titulo":"Criar um atendimento manualmente","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Toque em <b>Novo</b>."},{"h":"Em <b>Contato</b>, busque por nome ou número e escolha o contato."},{"h":"Escolha a <b>Fila</b> e toque em <b>Criar</b>."}]}],"busca":"atendimento e filas criar um atendimento manualmente toque em novo. em contato, busque por nome ou numero e escolha o contato. escolha a fila e toque em criar."},{"id":"4-receber-atendimentos-sozinhos-tempo-real","titulo":"Receber atendimentos sozinhos (tempo real)","admin":true,"blocos":[{"t":"p","h":"Para novos clientes entrarem na fila automaticamente, o recebimento em tempo real precisa estar ligado."},{"t":"ol","itens":[{"h":"No topo da tela, o aviso mostra <b>Recebimento em tempo real desligado</b> ou <b>ativo</b>."},{"h":"Quem tem permissão de gerir filas toca em <b>Ligar</b> (e confirma). Para parar, toque em <b>Desligar</b>."}]},{"t":"nota","tipo":"aviso","h":"desligar o recebimento em tempo real também para as Automações e o Chatbot desta conexão. O painel nunca liga isso sozinho."}],"busca":"atendimento e filas receber atendimentos sozinhos (tempo real) para novos clientes entrarem na fila automaticamente, o recebimento em tempo real precisa estar ligado. no topo da tela, o aviso mostra recebimento em tempo real desligado ou ativo. quem tem permissao de gerir filas toca em ligar (e confirma). para parar, toque em desligar. desligar o recebimento em tempo real tambem para as automacoes e o chatbot desta conexao. o painel nunca liga isso sozinho."},{"id":"4-criar-e-editar-filas","titulo":"Criar e editar filas","admin":true,"blocos":[{"t":"ol","itens":[{"h":"Toque em <b>Filas</b> (<b>Gerir filas</b>) e depois em <b>Nova fila</b>. Para uma fila existente, toque no lápis; use as setas para mudar a ordem e a lixeira para excluir.","img":"manual/img/filas-gerir.webp","alt":"Janela de gestão de filas"},{"h":"Preencha <b>Nome</b>, escolha a <b>Cor</b> e marque os <b>Atendentes da fila</b>."},{"h":"Escreva a <b>Mensagem de saudação</b> (enviada quando o cliente entra na fila) e a <b>Mensagem de ausência (fora do horário)</b>."},{"h":"Defina o <b>SLA — tempo máximo de espera (minutos, 0 = sem SLA)</b> e as <b>Cores pelo tempo sem resposta</b> (<b>Verde até</b>, <b>Amarelo até</b>, <b>Laranja até</b>, em minutos)."},{"h":"Marque <b>Fila padrão</b> para receber quem não escolheu fila."},{"h":"Toque em <b>Salvar</b>. O painel avisa <b>Fila salva</b>.","img":"manual/img/fila-editar.webp","alt":"Editor de fila"}]}],"busca":"atendimento e filas criar e editar filas toque em filas (gerir filas) e depois em nova fila. para uma fila existente, toque no lapis; use as setas para mudar a ordem e a lixeira para excluir. preencha nome, escolha a cor e marque os atendentes da fila. escreva a mensagem de saudacao (enviada quando o cliente entra na fila) e a mensagem de ausencia (fora do horario). defina o sla — tempo maximo de espera (minutos, 0 = sem sla) e as cores pelo tempo sem resposta (verde ate, amarelo ate, laranja ate, em minutos). marque fila padrao para receber quem nao escolheu fila. toque em salvar. o painel avisa fila salva."},{"id":"4-horario-de-atendimento-da-fila","titulo":"Horário de atendimento da fila","admin":true,"blocos":[{"t":"ol","itens":[{"h":"No editor da fila, marque <b>Usar horário de atendimento</b>."},{"h":"Para cada dia da semana (<b>Domingo</b> a <b>Sábado</b>), toque em <b>Faixa</b> e informe o horário de início e o horário de fim (até 4 faixas por dia). Dia sem faixa fica <b>fechado</b>."},{"h":"Fora do horário, o cliente recebe a <b>Mensagem de ausência</b>."},{"h":"Salve com <b>Salvar</b>."}]}],"busca":"atendimento e filas horario de atendimento da fila no editor da fila, marque usar horario de atendimento. para cada dia da semana (domingo a sabado), toque em faixa e informe o horario de inicio e o horario de fim (ate 4 faixas por dia). dia sem faixa fica fechado. fora do horario, o cliente recebe a mensagem de ausencia. salve com salvar."}]},{"n":5,"titulo":"Enviar","topicos":[{"id":"5-escolher-o-destinatario","titulo":"Escolher o destinatário","admin":false,"blocos":[{"t":"p","h":"A tela <b>Enviar</b> (botão <b>+</b> no meio da barra de baixo) manda mensagens para qualquer contato."},{"t":"ol","itens":[{"h":"Em <b>Para quem?</b>, digite um nome da sua lista de contatos ou um número, como (82) 99999-0001. Aparecem sugestões enquanto você digita."},{"h":"Toque numa sugestão para escolher, ou digite o número completo."},{"h":"Para limpar, toque no X ao lado do campo."},{"h":"A linha <b>Sua mensagem sairá assinada</b> mostra o nome que vai na assinatura."}]},{"t":"nota","tipo":"dica","h":"o rascunho é guardado: se você sair da tela, o destinatário e o texto voltam quando retornar."}],"busca":"enviar escolher o destinatario a tela enviar (botao + no meio da barra de baixo) manda mensagens para qualquer contato. em para quem?, digite um nome da sua lista de contatos ou um numero, como (82) 99999-0001. aparecem sugestoes enquanto voce digita. toque numa sugestao para escolher, ou digite o numero completo. para limpar, toque no x ao lado do campo. a linha sua mensagem saira assinada mostra o nome que vai na assinatura. o rascunho e guardado: se voce sair da tela, o destinatario e o texto voltam quando retornar."},{"id":"5-verificar-se-o-numero-tem-whatsapp","titulo":"Verificar se o número tem WhatsApp","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Depois de escolher o destinatário, toque em <b>Verificar número</b>."},{"h":"O painel mostra se o número existe no WhatsApp e qual é o nome dele."}]},{"t":"nota","tipo":"aviso","h":"este botão só aparece para quem tem permissão de verificar números."}],"busca":"enviar verificar se o numero tem whatsapp depois de escolher o destinatario, toque em verificar numero. o painel mostra se o numero existe no whatsapp e qual e o nome dele. este botao so aparece para quem tem permissao de verificar numeros."},{"id":"5-enviar-texto","titulo":"Enviar texto","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Na aba <b>Texto</b>, escreva em <b>Mensagem</b> (até 4096 caracteres; o contador mostra quanto falta)."},{"h":"Se quiser, ligue <b>Mostrar &quot;digitando…&quot; antes de enviar</b> e escolha 2, 3, 5 ou 8 segundos."},{"h":"Confira a <b>Pré-visualização</b> do balão."},{"h":"Toque em <b>Enviar</b>. A tela mostra <b>Enviada!</b> com as opções <b>Enviar outra</b> e <b>Abrir conversa</b>.","img":"manual/img/enviar-texto.webp","alt":"Aba Texto da tela Enviar"}]}],"busca":"enviar enviar texto na aba texto, escreva em mensagem (ate 4096 caracteres; o contador mostra quanto falta). se quiser, ligue mostrar \"digitando…\" antes de enviar e escolha 2, 3, 5 ou 8 segundos. confira a pre-visualizacao do balao. toque em enviar. a tela mostra enviada! com as opcoes enviar outra e abrir conversa."},{"id":"5-enviar-midia","titulo":"Enviar mídia","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Abra a aba <b>Mídia</b>."},{"h":"Toque em <b>Arquivo</b> (ou <b>Câmera</b>, no celular) e escolha imagem, vídeo, áudio, PDF, Word, Excel, TXT ou ZIP, até 25 MB."},{"h":"Escreva uma <b>Legenda (opcional)</b>."},{"h":"Toque em <b>Enviar</b>; uma barra de progresso acompanha o envio.","img":"manual/img/enviar-midia.webp","alt":"Aba Mídia da tela Enviar"}]}],"busca":"enviar enviar midia abra a aba midia. toque em arquivo (ou camera, no celular) e escolha imagem, video, audio, pdf, word, excel, txt ou zip, ate 25 mb. escreva uma legenda (opcional). toque em enviar; uma barra de progresso acompanha o envio."},{"id":"5-enviar-enquete","titulo":"Enviar enquete","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Abra a aba <b>Enquete</b>."},{"h":"Escreva a <b>Pergunta</b> e preencha de 2 a 12 opções; use <b>Adicionar opção</b> para criar mais."},{"h":"Ligue <b>Permitir várias respostas</b> se quiser."},{"h":"Toque em <b>Enviar</b>.","img":"manual/img/enviar-enquete.webp","alt":"Aba Enquete da tela Enviar"}]},{"t":"nota","tipo":"dica","h":"opções repetidas ou vazias são recusadas, com a mensagem indicando o que corrigir."}],"busca":"enviar enviar enquete abra a aba enquete. escreva a pergunta e preencha de 2 a 12 opcoes; use adicionar opcao para criar mais. ligue permitir varias respostas se quiser. toque em enviar. opcoes repetidas ou vazias sao recusadas, com a mensagem indicando o que corrigir."},{"id":"5-enviar-localizacao","titulo":"Enviar localização","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Abra a aba <b>Localização</b>."},{"h":"Toque em <b>Usar minha localização</b> ou digite <b>Latitude</b> e <b>Longitude</b>."},{"h":"Preencha o <b>Nome do local (opcional)</b> e o <b>Endereço (opcional)</b>. O link <b>Ver no mapa</b> ajuda a conferir."},{"h":"Toque em <b>Enviar</b>.","img":"manual/img/enviar-localizacao.webp","alt":"Aba Localização da tela Enviar"}]}],"busca":"enviar enviar localizacao abra a aba localizacao. toque em usar minha localizacao ou digite latitude e longitude. preencha o nome do local (opcional) e o endereco (opcional). o link ver no mapa ajuda a conferir. toque em enviar."},{"id":"5-enviar-contato","titulo":"Enviar contato","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Abra a aba <b>Contato</b>."},{"h":"Informe o <b>Nome do contato</b> e o <b>Número do contato</b> (com DDD)."},{"h":"Toque em <b>Enviar</b>. O destinatário recebe um cartão de contato que pode salvar.","img":"manual/img/enviar-contato.webp","alt":"Aba Contato da tela Enviar"}]}],"busca":"enviar enviar contato abra a aba contato. informe o nome do contato e o numero do contato (com ddd). toque em enviar. o destinatario recebe um cartao de contato que pode salvar."},{"id":"5-agendar-o-envio","titulo":"Agendar o envio","admin":false,"blocos":[{"t":"p","h":"Em vez de enviar agora, você pode marcar um dia e hora."},{"t":"ol","itens":[{"h":"Ligue o interruptor <b>Agendar</b>."},{"h":"Escolha a <b>Data e hora</b> (pelo menos 1 minuto à frente, no fuso do seu aparelho)."},{"h":"O botão muda para <b>Agendar</b>; toque nele. O painel avisa <b>Mensagem agendada!</b> e oferece <b>Ver agendadas</b>.","img":"manual/img/enviar-agendar.webp","alt":"Opção Agendar na tela Enviar"}]},{"t":"nota","tipo":"aviso","h":"só dá para agendar mensagens de <b>Texto</b> e <b>Mídia</b>. A assinatura com o seu nome é gravada no agendamento."}],"busca":"enviar agendar o envio em vez de enviar agora, voce pode marcar um dia e hora. ligue o interruptor agendar. escolha a data e hora (pelo menos 1 minuto a frente, no fuso do seu aparelho). o botao muda para agendar; toque nele. o painel avisa mensagem agendada! e oferece ver agendadas. so da para agendar mensagens de texto e midia. a assinatura com o seu nome e gravada no agendamento."}]},{"n":6,"titulo":"Agendadas","topicos":[{"id":"6-acompanhar-as-mensagens-agendadas","titulo":"Acompanhar as mensagens agendadas","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Abra <b>Agendadas</b> no menu."},{"h":"Os filtros <b>Pendentes</b>, <b>Enviadas</b>, <b>Com erro</b>, <b>Canceladas</b> e <b>Todas</b> mostram a contagem de cada grupo."},{"h":"Cada cartão mostra o contato, o dia e a hora, o texto e a assinatura com que vai sair.","img":"manual/img/agendadas.webp","alt":"Lista de mensagens agendadas"},{"h":"Toque em <b>Agendar</b> (canto superior) para criar um agendamento novo; você vai para a tela <b>Enviar</b>."}]},{"t":"nota","tipo":"dica","h":"o servidor envia as agendadas a cada minuto, no máximo cinco por rodada."}],"busca":"agendadas acompanhar as mensagens agendadas abra agendadas no menu. os filtros pendentes, enviadas, com erro, canceladas e todas mostram a contagem de cada grupo. cada cartao mostra o contato, o dia e a hora, o texto e a assinatura com que vai sair. toque em agendar (canto superior) para criar um agendamento novo; voce vai para a tela enviar. o servidor envia as agendadas a cada minuto, no maximo cinco por rodada."},{"id":"6-enviar-agora-reagendar-ou-cancelar","titulo":"Enviar agora, reagendar ou cancelar","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Em uma mensagem <b>pendente</b>, toque em <b>Enviar agora</b> para mandar na hora, <b>Reagendar</b> para mudar o horário ou <b>Cancelar</b> para desistir."},{"h":"Em <b>Reagendar</b>, escolha <b>Nova data e hora</b> ou use os atalhos <b>+30 min</b>, <b>+1 h</b> e <b>Amanhã 9h</b>, e toque em <b>Reagendar</b>."},{"h":"Mensagens com erro têm <b>Tentar enviar</b>; as canceladas podem ser reagendadas."}]},{"t":"nota","tipo":"aviso","h":"cancelar uma agendada não pode ser desfeito, mas você pode reagendá-la depois."}],"busca":"agendadas enviar agora, reagendar ou cancelar em uma mensagem pendente, toque em enviar agora para mandar na hora, reagendar para mudar o horario ou cancelar para desistir. em reagendar, escolha nova data e hora ou use os atalhos +30 min, +1 h e amanha 9h, e toque em reagendar. mensagens com erro tem tentar enviar; as canceladas podem ser reagendadas. cancelar uma agendada nao pode ser desfeito, mas voce pode reagenda-la depois."}]},{"n":7,"titulo":"Automações","topicos":[{"id":"7-o-que-sao-automacoes","titulo":"O que são automações","admin":false,"blocos":[{"t":"p","h":"Uma automação responde ou age sozinha quando acontece algo: <b>Quando</b> (gatilho) e <b>Então</b> (ações), com condições opcionais no meio."},{"t":"ol","itens":[{"h":"Abra <b>Automações</b> no menu."},{"h":"A aba <b>Automações</b> lista as regras e a aba <b>Registros</b> mostra o histórico do que cada uma fez."},{"h":"A ordem importa: as regras são avaliadas de cima para baixo. Use as setas para reordenar e a ação <b>Parar aqui</b> para impedir que as de baixo também respondam.","img":"manual/img/automacoes.webp","alt":"Lista de automações"}]},{"t":"nota","tipo":"aviso","h":"automações dependem do recebimento em tempo real (veja &quot;Ligar o recebimento em tempo real&quot;, logo adiante)."}],"busca":"automacoes o que sao automacoes uma automacao responde ou age sozinha quando acontece algo: quando (gatilho) e entao (acoes), com condicoes opcionais no meio. abra automacoes no menu. a aba automacoes lista as regras e a aba registros mostra o historico do que cada uma fez. a ordem importa: as regras sao avaliadas de cima para baixo. use as setas para reordenar e a acao parar aqui para impedir que as de baixo tambem respondam. automacoes dependem do recebimento em tempo real (veja \"ligar o recebimento em tempo real\", logo adiante)."},{"id":"7-criar-uma-automacao-a-partir-de-um-modelo","titulo":"Criar uma automação a partir de um modelo","admin":true,"blocos":[{"t":"ol","itens":[{"h":"Toque em <b>Modelos</b> (ou escolha um modelo na tela vazia): <b>Resposta de ausência</b>, <b>Boas-vindas</b> ou <b>Preço</b>."},{"h":"O editor abre já preenchido. Ajuste o texto e siga os passos do assistente."}]}],"busca":"automacoes criar uma automacao a partir de um modelo toque em modelos (ou escolha um modelo na tela vazia): resposta de ausencia, boas-vindas ou preco. o editor abre ja preenchido. ajuste o texto e siga os passos do assistente."},{"id":"7-escolher-o-gatilho-quando","titulo":"Escolher o gatilho (Quando)","admin":true,"blocos":[{"t":"ol","itens":[{"h":"Toque em <b>Nova automação</b>. O passo 1 é <b>Gatilho</b>."},{"h":"Dê um nome em <b>Nome da automação</b> e escolha <b>Quando ela deve começar?</b>:<br>- <b>Mensagem recebida:</b> quando o contato escrever certas palavras (defina <b>Palavras-chave</b> e <b>Como comparar?</b>).<br>- <b>Primeira mensagem do contato:</b> só na primeira vez que a pessoa fala com você.<br>- <b>Primeira mensagem do dia:</b> na primeira mensagem de cada pessoa em cada dia.<br>- <b>Qualquer mensagem:</b> toda mensagem recebida.<br>- <b>Agendado:</b> em dias e horários marcados.<br>- <b>Conexão desconectada:</b> quando o WhatsApp cair (você escolhe números para avisar)."},{"h":"Defina o <b>Limite de respostas por contato/hora</b> para evitar respostas em excesso (padrão 3)."},{"h":"Toque em <b>Continuar</b>.","img":"manual/img/automacao-editor.webp","alt":"Editor de automação, passo do gatilho"}]}],"busca":"automacoes escolher o gatilho (quando) toque em nova automacao. o passo 1 e gatilho. de um nome em nome da automacao e escolha quando ela deve comecar?:- mensagem recebida: quando o contato escrever certas palavras (defina palavras-chave e como comparar?).- primeira mensagem do contato: so na primeira vez que a pessoa fala com voce.- primeira mensagem do dia: na primeira mensagem de cada pessoa em cada dia.- qualquer mensagem: toda mensagem recebida.- agendado: em dias e horarios marcados.- conexao desconectada: quando o whatsapp cair (voce escolhe numeros para avisar). defina o limite de respostas por contato/hora para evitar respostas em excesso (padrao 3). toque em continuar."},{"id":"7-definir-as-condicoes","titulo":"Definir as condições","admin":true,"blocos":[{"t":"p","h":"O passo 2, <b>Condições</b>, é opcional: sem condições, a regra vale para todas as mensagens do gatilho."},{"t":"ol","itens":[{"h":"Escolha o <b>Tipo de conversa</b>: <b>Privada</b>, <b>Grupos</b> ou <b>As duas</b>."},{"h":"Em <b>Horário de funcionamento</b>, escolha <b>Qualquer hora</b>, <b>Dentro do horário</b> ou <b>Fora do horário</b> e informe <b>Abre às</b>, <b>Fecha às</b> e os <b>Dias de funcionamento</b>."},{"h":"Em <b>Contato</b>, escolha <b>Qualquer um</b>, <b>Só contato novo</b> ou <b>Só quem já falou</b>."},{"h":"Marque o <b>Tipo de mensagem</b> (texto, imagem, áudio etc.; nenhum marcado = todos)."},{"h":"Use <b>Só estes contatos</b> e <b>Nunca para estes contatos</b> (um número por linha) para limitar ou excluir pessoas."}]}],"busca":"automacoes definir as condicoes o passo 2, condicoes, e opcional: sem condicoes, a regra vale para todas as mensagens do gatilho. escolha o tipo de conversa: privada, grupos ou as duas. em horario de funcionamento, escolha qualquer hora, dentro do horario ou fora do horario e informe abre as, fecha as e os dias de funcionamento. em contato, escolha qualquer um, so contato novo ou so quem ja falou. marque o tipo de mensagem (texto, imagem, audio etc.; nenhum marcado = todos). use so estes contatos e nunca para estes contatos (um numero por linha) para limitar ou excluir pessoas."},{"id":"7-escolher-as-acoes-entao","titulo":"Escolher as ações (Então)","admin":true,"blocos":[{"t":"p","h":"No passo 3, <b>Ações</b>, você monta o que a automação faz, em ordem."},{"t":"ol","itens":[{"h":"Toque em <b>Adicionar ação</b> e escolha entre: <b>Responder com texto</b>, <b>Responder com mídia</b>, <b>Esperar</b>, <b>Marcar como lida</b>, <b>Chamar um webhook</b>, <b>Enviar para uma fila</b>, <b>Colocar etiqueta</b> e <b>Parar aqui</b>."},{"h":"Nos textos, use as variáveis <b>{nome}</b>, <b>{numero}</b>, <b>{data}</b>, <b>{hora}</b> e <b>{saudacao}</b>."},{"h":"Use o <b>Atraso antes desta ação</b> para a resposta parecer humana."},{"h":"Reordene com as setas ou remova com o X."}]},{"t":"nota","tipo":"aviso","h":"as esperas e atrasos somam, no máximo, 45 segundos."}],"busca":"automacoes escolher as acoes (entao) no passo 3, acoes, voce monta o que a automacao faz, em ordem. toque em adicionar acao e escolha entre: responder com texto, responder com midia, esperar, marcar como lida, chamar um webhook, enviar para uma fila, colocar etiqueta e parar aqui. nos textos, use as variaveis {nome}, {numero}, {data}, {hora} e {saudacao}. use o atraso antes desta acao para a resposta parecer humana. reordene com as setas ou remova com o x. as esperas e atrasos somam, no maximo, 45 segundos."},{"id":"7-testar-no-simulador","titulo":"Testar no simulador","admin":true,"blocos":[{"t":"p","h":"O passo 4, <b>Revisar e testar</b>, tem o <b>Simulador</b>: você vê o que a regra faria, sem enviar nada."},{"t":"ol","itens":[{"h":"Em <b>Se o contato enviar:</b>, escreva uma mensagem de exemplo."},{"h":"Marque, se quiser, <b>Grupo</b>, <b>Contato novo</b> ou <b>Fora do horário</b>."},{"h":"Toque em <b>Simular</b>. O painel lista cada etapa e se a regra casaria ou não.","img":"manual/img/automacao-simulador.webp","alt":"Simulador de automação"}]}],"busca":"automacoes testar no simulador o passo 4, revisar e testar, tem o simulador: voce ve o que a regra faria, sem enviar nada. em se o contato enviar:, escreva uma mensagem de exemplo. marque, se quiser, grupo, contato novo ou fora do horario. toque em simular. o painel lista cada etapa e se a regra casaria ou nao."},{"id":"7-modo-teste-ou-ao-vivo","titulo":"Modo TESTE ou AO VIVO","admin":true,"blocos":[{"t":"ol","itens":[{"h":"No passo 4, escolha o <b>Modo</b>:<br>- <b>TESTE:</b> avalia e registra, mas NÃO envia nada.<br>- <b>AO VIVO:</b> responde pessoas de verdade."},{"h":"Marque <b>Ligar a automação ao salvar</b> se quiser ativá-la já."},{"h":"Toque em <b>Salvar</b>. Uma automação nova sempre começa desligada e em TESTE."},{"h":"Na lista, toque no selo <b>TESTE</b>/<b>AO VIVO</b> para trocar o modo e use o interruptor para ligar e desligar."}]},{"t":"nota","tipo":"dica","h":"deixe em TESTE por um tempo e confira a aba <b>Registros</b>; só passe para AO VIVO quando estiver satisfeito."}],"busca":"automacoes modo teste ou ao vivo no passo 4, escolha o modo:- teste: avalia e registra, mas nao envia nada.- ao vivo: responde pessoas de verdade. marque ligar a automacao ao salvar se quiser ativa-la ja. toque em salvar. uma automacao nova sempre comeca desligada e em teste. na lista, toque no selo teste/ao vivo para trocar o modo e use o interruptor para ligar e desligar. deixe em teste por um tempo e confira a aba registros; so passe para ao vivo quando estiver satisfeito."},{"id":"7-ligar-o-recebimento-em-tempo-real","titulo":"Ligar o recebimento em tempo real","admin":true,"blocos":[{"t":"ol","itens":[{"h":"No topo da tela Automações, o aviso informa <b>Recebimento em tempo real ligado</b> ou <b>desligado</b>."},{"h":"Se estiver desligado, toque em <b>Ligar recebimento</b> e confirme. Para parar, <b>Desligar recebimento</b>.","img":"manual/img/automacao-webhook.webp","alt":"Aviso de recebimento em tempo real"}]},{"t":"nota","tipo":"aviso","h":"o painel nunca liga isso sozinho. Sem ele, as automações por mensagem não disparam."}],"busca":"automacoes ligar o recebimento em tempo real no topo da tela automacoes, o aviso informa recebimento em tempo real ligado ou desligado. se estiver desligado, toque em ligar recebimento e confirme. para parar, desligar recebimento. o painel nunca liga isso sozinho. sem ele, as automacoes por mensagem nao disparam."},{"id":"7-acompanhar-os-registros","titulo":"Acompanhar os registros","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Abra a aba <b>Registros</b>."},{"h":"Filtre por <b>Todos</b>, <b>Executou</b>, <b>Ignorou</b>, <b>Erro</b> ou <b>Teste</b>."},{"h":"Cada linha mostra a automação, o número, a hora e o detalhe do resultado. Toque em <b>Carregar mais</b> para ver o histórico antigo."}]}],"busca":"automacoes acompanhar os registros abra a aba registros. filtre por todos, executou, ignorou, erro ou teste. cada linha mostra a automacao, o numero, a hora e o detalhe do resultado. toque em carregar mais para ver o historico antigo."},{"id":"7-duplicar-e-excluir","titulo":"Duplicar e excluir","admin":true,"blocos":[{"t":"ol","itens":[{"h":"Na lista, toque no ícone de copiar para duplicar (a cópia nasce desligada, em TESTE)."},{"h":"Toque na lixeira para excluir e confirme."}]}],"busca":"automacoes duplicar e excluir na lista, toque no icone de copiar para duplicar (a copia nasce desligada, em teste). toque na lixeira para excluir e confirme."}]},{"n":8,"titulo":"Chatbot","topicos":[{"id":"8-o-que-e-o-chatbot","titulo":"O que é o chatbot","admin":false,"blocos":[{"t":"p","h":"O chatbot conversa com o cliente por etapas (menu, perguntas, transferência para atendente). É um fluxo montado por você."},{"t":"ol","itens":[{"h":"Abra <b>Chatbot</b> no menu."},{"h":"As abas são <b>Fluxos</b>, <b>Sessões</b> (clientes conversando agora) e <b>Registros</b> (cada passo do robô)."},{"h":"O banner no alto mostra se o <b>Recebimento em tempo real</b> está ligado; sem ele o chatbot não recebe mensagens. Toque em <b>Ligar recebimento</b> (ou <b>Desligar</b>).","img":"manual/img/chatbot.webp","alt":"Lista de fluxos do chatbot"}]},{"t":"nota","tipo":"aviso","h":"o chatbot só responde de verdade quando o fluxo está <b>ativo</b> e em <b>AO VIVO</b>."}],"busca":"chatbot o que e o chatbot o chatbot conversa com o cliente por etapas (menu, perguntas, transferencia para atendente). e um fluxo montado por voce. abra chatbot no menu. as abas sao fluxos, sessoes (clientes conversando agora) e registros (cada passo do robo). o banner no alto mostra se o recebimento em tempo real esta ligado; sem ele o chatbot nao recebe mensagens. toque em ligar recebimento (ou desligar). o chatbot so responde de verdade quando o fluxo esta ativo e em ao vivo."},{"id":"8-criar-um-fluxo-a-partir-de-um-modelo","titulo":"Criar um fluxo a partir de um modelo","admin":true,"blocos":[{"t":"ol","itens":[{"h":"Na tela vazia (ou em <b>Criar a partir de um modelo</b>), escolha <b>Menu de atendimento</b>, <b>Horário e endereço</b> ou <b>Orçamento</b>."},{"h":"O editor abre com as etapas prontas. Ajuste os textos."}]}],"busca":"chatbot criar um fluxo a partir de um modelo na tela vazia (ou em criar a partir de um modelo), escolha menu de atendimento, horario e endereco ou orcamento. o editor abre com as etapas prontas. ajuste os textos."},{"id":"8-montar-as-etapas-do-fluxo","titulo":"Montar as etapas do fluxo","admin":true,"blocos":[{"t":"ol","itens":[{"h":"Toque em <b>Novo fluxo</b> e dê um <b>Nome do fluxo</b>."},{"h":"Em <b>Quando começa</b>, escolha <b>Primeira mensagem do contato</b>, <b>Palavras-chave</b> (separe por vírgula) ou <b>Toda mensagem sem atendimento</b>."},{"h":"Na aba <b>Fluxo</b>, toque em <b>Adicionar</b> e escolha a etapa: <b>Mensagem</b>, <b>Menu</b>, <b>Pergunta</b>, <b>Transferir</b>, <b>Encerrar</b> ou <b>Webhook</b>.<br>- <b>Menu:</b> o cliente responde com o número da opção; cada opção leva a uma etapa.<br>- <b>Pergunta:</b> guarda a resposta numa variável (por exemplo, nome) que você usa depois como {{nome}}.<br>- <b>Transferir:</b> passa para um atendente na fila escolhida."},{"h":"Em cada etapa escolha <b>Depois disso, ir para</b> a próxima etapa."},{"h":"A aba <b>Mapa</b> mostra uma visão geral; etapas inalcançáveis ficam em âmbar e precisam ser ligadas ou excluídas."},{"h":"Ajuste as regras gerais: <b>Mensagem quando o cliente responde algo inválido</b>, <b>Tentativas inválidas permitidas</b>, <b>Ao exceder as tentativas</b> (<b>Transferir para atendente</b> ou <b>Encerrar a conversa</b>) e <b>Expirar a sessão após (minutos sem resposta)</b>. Também é possível limitar ao horário comercial."},{"h":"Toque em <b>Salvar fluxo</b>.","img":"manual/img/chatbot-editor.webp","alt":"Editor de fluxo do chatbot"}]}],"busca":"chatbot montar as etapas do fluxo toque em novo fluxo e de um nome do fluxo. em quando comeca, escolha primeira mensagem do contato, palavras-chave (separe por virgula) ou toda mensagem sem atendimento. na aba fluxo, toque em adicionar e escolha a etapa: mensagem, menu, pergunta, transferir, encerrar ou webhook.- menu: o cliente responde com o numero da opcao; cada opcao leva a uma etapa.- pergunta: guarda a resposta numa variavel (por exemplo, nome) que voce usa depois como {{nome}}.- transferir: passa para um atendente na fila escolhida. em cada etapa escolha depois disso, ir para a proxima etapa. a aba mapa mostra uma visao geral; etapas inalcancaveis ficam em ambar e precisam ser ligadas ou excluidas. ajuste as regras gerais: mensagem quando o cliente responde algo invalido, tentativas invalidas permitidas, ao exceder as tentativas (transferir para atendente ou encerrar a conversa) e expirar a sessao apos (minutos sem resposta). tambem e possivel limitar ao horario comercial. toque em salvar fluxo."},{"id":"8-testar-no-simulador","titulo":"Testar no simulador","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No editor, abra a aba <b>Simulador</b>."},{"h":"Digite no campo <b>Digite como o cliente…</b> e envie; o robô responde como responderia no WhatsApp."},{"h":"Toque em <b>Reiniciar</b> para recomeçar a conversa."},{"h":"Se mudou o fluxo, toque em <b>Salvar e simular</b>.","img":"manual/img/chatbot-simulador.webp","alt":"Simulador do chatbot"}]},{"t":"nota","tipo":"dica","h":"é uma simulação interna: nada é enviado a ninguém."}],"busca":"chatbot testar no simulador no editor, abra a aba simulador. digite no campo digite como o cliente… e envie; o robo responde como responderia no whatsapp. toque em reiniciar para recomecar a conversa. se mudou o fluxo, toque em salvar e simular. e uma simulacao interna: nada e enviado a ninguem."},{"id":"8-ativar-modo-teste-x-ao-vivo","titulo":"Ativar, modo TESTE x AO VIVO","admin":true,"blocos":[{"t":"ol","itens":[{"h":"Na lista de fluxos, use o interruptor para ativar ou desativar."},{"h":"Toque em <b>Pôr AO VIVO</b> para responder clientes de verdade, ou em <b>Voltar p/ teste</b> para só registrar."},{"h":"Use <b>Duplicar</b> (a cópia nasce inativa e em teste) ou a lixeira para excluir."}]}],"busca":"chatbot ativar, modo teste x ao vivo na lista de fluxos, use o interruptor para ativar ou desativar. toque em por ao vivo para responder clientes de verdade, ou em voltar p/ teste para so registrar. use duplicar (a copia nasce inativa e em teste) ou a lixeira para excluir."},{"id":"8-acompanhar-as-sessoes","titulo":"Acompanhar as sessões","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Na aba <b>Sessões</b>, veja os clientes que estão num fluxo agora."},{"h":"Toque no ícone de conversa para abrir o chat, ou em <b>Encerrar</b> para finalizar a sessão."},{"h":"Na aba <b>Registros</b> aparece cada passo do robô."}]},{"t":"nota","tipo":"dica","h":"o cliente pode digitar &quot;sair&quot;, &quot;encerrar&quot; ou &quot;cancelar&quot; para sair do fluxo."}],"busca":"chatbot acompanhar as sessoes na aba sessoes, veja os clientes que estao num fluxo agora. toque no icone de conversa para abrir o chat, ou em encerrar para finalizar a sessao. na aba registros aparece cada passo do robo. o cliente pode digitar \"sair\", \"encerrar\" ou \"cancelar\" para sair do fluxo."}]},{"n":9,"titulo":"Campanhas e listas","topicos":[{"id":"9-antes-de-comecar-limites-anti-bloqueio","titulo":"Antes de começar: limites anti-bloqueio","admin":false,"blocos":[{"t":"p","h":"Campanha é o envio de uma mesma mensagem para muitas pessoas de uma lista. O WhatsApp pode bloquear números que mandam muitas mensagens iguais depressa demais."},{"t":"ol","itens":[{"h":"Use apenas listas de pessoas que esperam receber a sua mensagem."},{"h":"Comece com poucas mensagens por dia em números novos."},{"h":"Prefira o perfil <b>Seguro</b>, que espera de 20 a 60 segundos entre mensagens e limita a 200 por dia."}]},{"t":"nota","tipo":"aviso","h":"o envio em massa pode fazer o WhatsApp banir o número. O painel pede confirmação extra antes de iniciar."},{"t":"img","src":"manual/img/campanhas.webp","alt":"Tela de campanhas"}],"busca":"campanhas e listas antes de comecar: limites anti-bloqueio campanha e o envio de uma mesma mensagem para muitas pessoas de uma lista. o whatsapp pode bloquear numeros que mandam muitas mensagens iguais depressa demais. use apenas listas de pessoas que esperam receber a sua mensagem. comece com poucas mensagens por dia em numeros novos. prefira o perfil seguro, que espera de 20 a 60 segundos entre mensagens e limita a 200 por dia. o envio em massa pode fazer o whatsapp banir o numero. o painel pede confirmacao extra antes de iniciar. "},{"id":"9-criar-uma-lista-de-contatos","titulo":"Criar uma lista de contatos","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Abra <b>Campanhas</b> e toque na aba <b>Listas</b>."},{"h":"Toque em <b>Nova lista</b>, escreva o <b>Nome da lista</b> (por exemplo, &quot;Clientes de Maceió&quot;) e toque em salvar."},{"h":"Toque na lista para abrir. O topo mostra o total de contatos e quantos pediram para sair (opt-out).","img":"manual/img/listas.webp","alt":"Lista de listas de contatos"}]}],"busca":"campanhas e listas criar uma lista de contatos abra campanhas e toque na aba listas. toque em nova lista, escreva o nome da lista (por exemplo, \"clientes de maceio\") e toque em salvar. toque na lista para abrir. o topo mostra o total de contatos e quantos pediram para sair (opt-out)."},{"id":"9-adicionar-contatos-a-lista","titulo":"Adicionar contatos à lista","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Dentro da lista, toque em <b>Importar</b> (<b>Adicionar contatos</b>)."},{"h":"Na aba <b>Colar</b>, cole uma linha por contato no formato <code>nome; número</code> (por exemplo <code>Maria Souza; 82999990001</code>), ou carregue um arquivo CSV de até 2 MB."},{"h":"A revisão mostra quantos são válidos, inválidos e duplicados. Marque os que quer manter."},{"h":"Na aba <b>Contatos</b>, busque na sua agenda e marque quem deseja incluir."},{"h":"Confirme com o botão de adicionar. Para tirar alguém, toque no X ao lado do nome.","img":"manual/img/lista-detalhe.webp","alt":"Detalhe de uma lista de contatos"}]}],"busca":"campanhas e listas adicionar contatos a lista dentro da lista, toque em importar (adicionar contatos). na aba colar, cole uma linha por contato no formato nome; numero (por exemplo maria souza; 82999990001), ou carregue um arquivo csv de ate 2 mb. a revisao mostra quantos sao validos, invalidos e duplicados. marque os que quer manter. na aba contatos, busque na sua agenda e marque quem deseja incluir. confirme com o botao de adicionar. para tirar alguem, toque no x ao lado do nome."},{"id":"9-opt-out-quem-pede-para-sair","titulo":"Opt-out (quem pede para sair)","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Quem responder uma campanha com <b>SAIR</b>, <b>PARAR</b>, <b>PARE</b>, <b>STOP</b>, <b>DESCADASTRAR</b> ou frases como &quot;quero sair&quot; é marcado como opt-out."},{"h":"Esses contatos aparecem com marcação própria na lista e <b>nunca mais recebem</b> campanhas daquela conexão."},{"h":"A contagem <b>não receberão (opt-out)</b> aparece ao escolher a lista."}]},{"t":"nota","tipo":"aviso","h":"isso depende do recebimento em tempo real ligado."}],"busca":"campanhas e listas opt-out (quem pede para sair) quem responder uma campanha com sair, parar, pare, stop, descadastrar ou frases como \"quero sair\" e marcado como opt-out. esses contatos aparecem com marcacao propria na lista e nunca mais recebem campanhas daquela conexao. a contagem nao receberao (opt-out) aparece ao escolher a lista. isso depende do recebimento em tempo real ligado."},{"id":"9-criar-uma-campanha-assistente-em-4-passos","titulo":"Criar uma campanha (assistente em 4 passos)","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Na aba <b>Campanhas</b>, toque em <b>Nova campanha</b>."},{"h":"<b>Passo 1, Escolha a lista:</b> toque na lista de destino."},{"h":"<b>Passo 2, Escreva a mensagem:</b> dê o <b>Nome da campanha (só você vê)</b> e escolha entre <b>Texto</b> e <b>Mídia</b> (arquivo de até 16 MB, com legenda). Use os botões <b>{nome}</b> e <b>{primeiro_nome}</b> para personalizar. Veja que a mensagem sai assinada com o seu nome."},{"h":"<b>Passo 3, Limites anti-bloqueio:</b> escolha <b>Seguro</b>, <b>Moderado</b> ou <b>Rápido</b> (marcado como arriscado), ou ajuste o <b>Intervalo entre mensagens (segundos)</b>, o <b>Limite por dia (mensagens)</b> e a <b>Janela de horário</b>. A estimativa mostra quanto tempo vai levar."},{"h":"<b>Passo 4, Revisar e iniciar:</b> confira o resumo e o balão de pré-visualização. Toque em <b>Salvar rascunho</b> para guardar ou em <b>Revisar e iniciar…</b>.","img":"manual/img/campanha-assistente.webp","alt":"Assistente de criação de campanha"}]}],"busca":"campanhas e listas criar uma campanha (assistente em 4 passos) na aba campanhas, toque em nova campanha. passo 1, escolha a lista: toque na lista de destino. passo 2, escreva a mensagem: de o nome da campanha (so voce ve) e escolha entre texto e midia (arquivo de ate 16 mb, com legenda). use os botoes {nome} e {primeiro_nome} para personalizar. veja que a mensagem sai assinada com o seu nome. passo 3, limites anti-bloqueio: escolha seguro, moderado ou rapido (marcado como arriscado), ou ajuste o intervalo entre mensagens (segundos), o limite por dia (mensagens) e a janela de horario. a estimativa mostra quanto tempo vai levar. passo 4, revisar e iniciar: confira o resumo e o balao de pre-visualizacao. toque em salvar rascunho para guardar ou em revisar e iniciar…."},{"id":"9-confirmar-e-iniciar-o-envio","titulo":"Confirmar e iniciar o envio","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Ao tocar em <b>Revisar e iniciar…</b>, aparece <b>Confirmar envio em massa</b>, com o aviso de risco de bloqueio."},{"h":"Digite o número total de destinatários mostrado na tela. O botão só libera quando o número confere."},{"h":"Toque em <b>Iniciar envio</b>. O painel avisa <b>Campanha iniciada! Acompanhe o envio ao vivo.</b>"}]},{"t":"nota","tipo":"dica","h":"quem não tem a permissão de iniciar pode apenas salvar rascunhos."}],"busca":"campanhas e listas confirmar e iniciar o envio ao tocar em revisar e iniciar…, aparece confirmar envio em massa, com o aviso de risco de bloqueio. digite o numero total de destinatarios mostrado na tela. o botao so libera quando o numero confere. toque em iniciar envio. o painel avisa campanha iniciada! acompanhe o envio ao vivo. quem nao tem a permissao de iniciar pode apenas salvar rascunhos."},{"id":"9-acompanhar-pausar-e-cancelar","titulo":"Acompanhar, pausar e cancelar","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Na lista de campanhas, cada cartão mostra <b>enviados</b>, <b>falhas</b>, <b>na fila</b> e <b>pulados</b>; toque num número para ver os destinatários daquele grupo."},{"h":"Use <b>Pausar</b>, <b>Retomar</b> ou <b>Cancelar</b> durante o envio. <b>Editar</b> e <b>Excluir</b> ficam disponíveis em rascunhos, concluídas e canceladas."},{"h":"Se o limite do dia for atingido, o envio pausa e continua no dia seguinte, dentro da janela de horário."}]}],"busca":"campanhas e listas acompanhar, pausar e cancelar na lista de campanhas, cada cartao mostra enviados, falhas, na fila e pulados; toque num numero para ver os destinatarios daquele grupo. use pausar, retomar ou cancelar durante o envio. editar e excluir ficam disponiveis em rascunhos, concluidas e canceladas. se o limite do dia for atingido, o envio pausa e continua no dia seguinte, dentro da janela de horario."}]},{"n":10,"titulo":"Contatos, grupos, respostas rápidas, etiquetas e notas","topicos":[{"id":"10-buscar-contatos-e-iniciar-uma-conversa","titulo":"Buscar contatos e iniciar uma conversa","admin":false,"blocos":[{"t":"p","h":"Na tela <b>Contatos</b> você vê todos os contatos da conexão escolhida, em ordem alfabética, com rolagem infinita."},{"t":"ol","itens":[{"h":"No menu, abra <b>Contatos</b>.","img":"manual/img/contatos.webp","alt":"Lista de contatos"},{"h":"Digite no campo <b>Buscar por nome ou número</b>. A busca acontece sozinha, depois de uma pequena pausa na digitação. Toque no <b>X</b> para limpar."},{"h":"Sem busca, use o índice de letras na lateral direita para pular direto para uma letra."},{"h":"Toque em <b>Conversar</b> para abrir a conversa com a pessoa, ou em <b>Enviar</b> para abrir a tela Enviar já com o destinatário preenchido."},{"h":"Se a lista estiver desatualizada, toque em <b>Atualizar lista</b>. O total de contatos aparece ao lado."}]},{"t":"nota","tipo":"dica","h":"os botões <b>Conversar</b> e <b>Enviar</b> só aparecem se o seu usuário tiver essas permissões."}],"busca":"contatos, grupos, respostas rapidas, etiquetas e notas buscar contatos e iniciar uma conversa na tela contatos voce ve todos os contatos da conexao escolhida, em ordem alfabetica, com rolagem infinita. no menu, abra contatos. digite no campo buscar por nome ou numero. a busca acontece sozinha, depois de uma pequena pausa na digitacao. toque no x para limpar. sem busca, use o indice de letras na lateral direita para pular direto para uma letra. toque em conversar para abrir a conversa com a pessoa, ou em enviar para abrir a tela enviar ja com o destinatario preenchido. se a lista estiver desatualizada, toque em atualizar lista. o total de contatos aparece ao lado. os botoes conversar e enviar so aparecem se o seu usuario tiver essas permissoes."},{"id":"10-verificar-se-um-numero-tem-whatsapp","titulo":"Verificar se um número tem WhatsApp","admin":false,"blocos":[{"t":"p","h":"O cartão <b>Verificar número</b> consulta o WhatsApp para saber se um número existe, sem enviar nada para a pessoa."},{"t":"ol","itens":[{"h":"Em <b>Contatos</b>, localize o cartão <b>Verificar número</b>."},{"h":"Digite o número com DDD, por exemplo <code>82 99999-0001</code>. Se você digitar só DDD e número, o painel acrescenta o 55 do Brasil sozinho."},{"h":"Toque em <b>Verificar</b>.","img":"manual/img/contato-verificar.webp","alt":"Resultado da verificação de número"},{"h":"Se o número tiver WhatsApp, aparecem o nome (quando houver), o número formatado e os botões <b>Conversar</b> e <b>Enviar</b>. Se não tiver, aparece &quot;Este número não tem WhatsApp&quot;."}]},{"t":"nota","tipo":"aviso","h":"números com menos de 10 dígitos são recusados com a mensagem pedindo o DDD."}],"busca":"contatos, grupos, respostas rapidas, etiquetas e notas verificar se um numero tem whatsapp o cartao verificar numero consulta o whatsapp para saber se um numero existe, sem enviar nada para a pessoa. em contatos, localize o cartao verificar numero. digite o numero com ddd, por exemplo 82 99999-0001. se voce digitar so ddd e numero, o painel acrescenta o 55 do brasil sozinho. toque em verificar. se o numero tiver whatsapp, aparecem o nome (quando houver), o numero formatado e os botoes conversar e enviar. se nao tiver, aparece \"este numero nao tem whatsapp\". numeros com menos de 10 digitos sao recusados com a mensagem pedindo o ddd."},{"id":"10-ver-grupos-e-copiar-o-link-de-convite","titulo":"Ver grupos e copiar o link de convite","admin":false,"blocos":[{"t":"p","h":"A tela <b>Grupos</b> é somente de leitura: mostra os grupos do WhatsApp conectado e seus participantes. Não é possível criar grupos, sair deles nem remover pessoas por aqui."},{"t":"ol","itens":[{"h":"No menu, abra <b>Grupos</b>.","img":"manual/img/grupos.webp","alt":"Lista de grupos"},{"h":"Use <b>Buscar grupo por nome…</b> para filtrar. A lista se atualiza sozinha a cada minuto (selo <b>ao vivo</b>)."},{"h":"Toque em um grupo para abrir o detalhe.","img":"manual/img/grupo-detalhe.webp","alt":"Detalhe do grupo com participantes"},{"h":"No detalhe você vê a descrição, o número de participantes e a lista deles, com o selo <b>admin</b> para quem administra. Quando há 8 ou mais participantes aparece o campo <b>Buscar participante…</b>."},{"h":"Toque em <b>Conversar</b> ou <b>Enviar mensagem</b> para falar com o grupo."},{"h":"Toque em <b>Copiar link de convite</b> para copiar o link. Se você não for administrador do grupo, o WhatsApp pode negar o link."}]},{"t":"nota","tipo":"dica","h":"sem a permissão de convite, o botão é substituído por um aviso com cadeado."}],"busca":"contatos, grupos, respostas rapidas, etiquetas e notas ver grupos e copiar o link de convite a tela grupos e somente de leitura: mostra os grupos do whatsapp conectado e seus participantes. nao e possivel criar grupos, sair deles nem remover pessoas por aqui. no menu, abra grupos. use buscar grupo por nome… para filtrar. a lista se atualiza sozinha a cada minuto (selo ao vivo). toque em um grupo para abrir o detalhe. no detalhe voce ve a descricao, o numero de participantes e a lista deles, com o selo admin para quem administra. quando ha 8 ou mais participantes aparece o campo buscar participante…. toque em conversar ou enviar mensagem para falar com o grupo. toque em copiar link de convite para copiar o link. se voce nao for administrador do grupo, o whatsapp pode negar o link. sem a permissao de convite, o botao e substituido por um aviso com cadeado."},{"id":"10-criar-respostas-rapidas","titulo":"Criar respostas rápidas","admin":false,"blocos":[{"t":"p","h":"Respostas rápidas são textos prontos (com atalho) para as mensagens que você repete todo dia."},{"t":"ol","itens":[{"h":"No menu, abra <b>Respostas rápidas</b>.","img":"manual/img/respostas.webp","alt":"Lista de respostas rápidas"},{"h":"Toque em <b>Nova</b>. Se a lista estiver vazia, você também pode tocar num dos exemplos prontos (como <b>Saudação</b> ou <b>Horário de funcionamento</b>) para começar com o texto preenchido."},{"h":"Preencha o <b>Atalho</b> (sem a barra; só letras, números, <code>_</code> e <code>-</code>), o <b>Título</b> e o <b>Texto</b>.","img":"manual/img/resposta-editar.webp","alt":"Editor de resposta rápida"},{"h":"Para personalizar, toque nas variáveis acima do texto: <code>{nome}</code>, <code>{numero}</code>, <code>{saudacao}</code> (bom dia, boa tarde ou boa noite) e <code>{atendente}</code> (o seu nome). A <b>Prévia</b> mostra como a mensagem vai ficar."},{"h":"Se quiser, anexe uma imagem ou documento (até 5 MB) em <b>Anexo (opcional)</b>."},{"h":"Em <b>Quem pode usar</b>, escolha <b>Pessoal (só eu)</b>, <b>Esta conexão</b> ou <b>Global (todas)</b>. As duas últimas exigem permissão de editar respostas."},{"h":"Toque em <b>Salvar</b>."}]},{"t":"nota","tipo":"dica","h":"use os filtros <b>Todas</b>, <b>Pessoais</b>, <b>Conexão</b> e <b>Globais</b> para achar rápido. Em cada cartão há <b>Copiar</b>, <b>Editar</b> e a lixeira (com confirmação)."}],"busca":"contatos, grupos, respostas rapidas, etiquetas e notas criar respostas rapidas respostas rapidas sao textos prontos (com atalho) para as mensagens que voce repete todo dia. no menu, abra respostas rapidas. toque em nova. se a lista estiver vazia, voce tambem pode tocar num dos exemplos prontos (como saudacao ou horario de funcionamento) para comecar com o texto preenchido. preencha o atalho (sem a barra; so letras, numeros, _ e -), o titulo e o texto. para personalizar, toque nas variaveis acima do texto: {nome}, {numero}, {saudacao} (bom dia, boa tarde ou boa noite) e {atendente} (o seu nome). a previa mostra como a mensagem vai ficar. se quiser, anexe uma imagem ou documento (ate 5 mb) em anexo (opcional). em quem pode usar, escolha pessoal (so eu), esta conexao ou global (todas). as duas ultimas exigem permissao de editar respostas. toque em salvar. use os filtros todas, pessoais, conexao e globais para achar rapido. em cada cartao ha copiar, editar e a lixeira (com confirmacao)."},{"id":"10-usar-uma-resposta-rapida-numa-conversa","titulo":"Usar uma resposta rápida numa conversa","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Abra uma conversa em <b>Conversas</b>."},{"h":"No campo de mensagem, digite <code>/</code> seguido do começo do atalho, ou toque no ícone de raio."},{"h":"Escolha a resposta na lista, que tem busca por atalho, título e texto. As variáveis são preenchidas com os dados do contato."},{"h":"Revise o texto no campo de mensagem e envie."}]},{"t":"nota","tipo":"aviso","h":"é preciso ter a permissão de usar respostas rápidas; sem ela o painel avisa com uma mensagem."}],"busca":"contatos, grupos, respostas rapidas, etiquetas e notas usar uma resposta rapida numa conversa abra uma conversa em conversas. no campo de mensagem, digite / seguido do comeco do atalho, ou toque no icone de raio. escolha a resposta na lista, que tem busca por atalho, titulo e texto. as variaveis sao preenchidas com os dados do contato. revise o texto no campo de mensagem e envie. e preciso ter a permissao de usar respostas rapidas; sem ela o painel avisa com uma mensagem."},{"id":"10-organizar-com-etiquetas","titulo":"Organizar com etiquetas","admin":false,"blocos":[{"t":"p","h":"Etiquetas são marcadores coloridos para classificar conversas (por exemplo, &quot;Cliente VIP&quot;)."},{"t":"ol","itens":[{"h":"No menu, abra <b>Etiquetas e notas</b> e fique na aba <b>Etiquetas</b>.","img":"manual/img/etiquetas.webp","alt":"Etiquetas"},{"h":"Toque em <b>Nova etiqueta</b>, escreva o <b>Nome</b>, escolha uma das 12 cores e confira a <b>Prévia</b>. Toque em <b>Salvar</b>."},{"h":"Cada cartão mostra quantas conversas usam a etiqueta. Toque na contagem para ver a lista de conversas e abrir uma delas."},{"h":"Use <b>Editar</b> para renomear ou trocar a cor, e <b>Excluir</b> para apagar (o painel pede confirmação)."},{"h":"Para aplicar numa conversa, abra a conversa e toque no botão de etiquetas. Marque as que valem para o contato; também é possível criar uma etiqueta nova ali mesmo, em <b>Nova etiqueta…</b> e <b>Criar</b>."}]},{"t":"nota","tipo":"dica","h":"quem só tem permissão de ver etiquetas enxerga as marcações, mas não consegue criar nem aplicar."}],"busca":"contatos, grupos, respostas rapidas, etiquetas e notas organizar com etiquetas etiquetas sao marcadores coloridos para classificar conversas (por exemplo, \"cliente vip\"). no menu, abra etiquetas e notas e fique na aba etiquetas. toque em nova etiqueta, escreva o nome, escolha uma das 12 cores e confira a previa. toque em salvar. cada cartao mostra quantas conversas usam a etiqueta. toque na contagem para ver a lista de conversas e abrir uma delas. use editar para renomear ou trocar a cor, e excluir para apagar (o painel pede confirmacao). para aplicar numa conversa, abra a conversa e toque no botao de etiquetas. marque as que valem para o contato; tambem e possivel criar uma etiqueta nova ali mesmo, em nova etiqueta… e criar. quem so tem permissao de ver etiquetas enxerga as marcacoes, mas nao consegue criar nem aplicar."},{"id":"10-registrar-notas-internas","titulo":"Registrar notas internas","admin":false,"blocos":[{"t":"p","h":"Notas são anotações da equipe sobre um contato. A pessoa atendida nunca as recebe."},{"t":"ol","itens":[{"h":"Dentro de uma conversa, toque no botão de notas.","img":"manual/img/notas.webp","alt":"Notas internas de uma conversa"},{"h":"Escreva em <b>Escreva uma nota interna…</b> (até 2000 caracteres) e toque em adicionar."},{"h":"Use <b>Fixar</b> para deixar uma nota importante no topo (e <b>Desafixar</b> para tirar), ou a lixeira para excluir, com confirmação."},{"h":"Para ver as notas mais recentes de todas as conversas, abra <b>Etiquetas e notas</b> e toque na aba <b>Notas recentes</b>."}]}],"busca":"contatos, grupos, respostas rapidas, etiquetas e notas registrar notas internas notas sao anotacoes da equipe sobre um contato. a pessoa atendida nunca as recebe. dentro de uma conversa, toque no botao de notas. escreva em escreva uma nota interna… (ate 2000 caracteres) e toque em adicionar. use fixar para deixar uma nota importante no topo (e desafixar para tirar), ou a lixeira para excluir, com confirmacao. para ver as notas mais recentes de todas as conversas, abra etiquetas e notas e toque na aba notas recentes."}]},{"n":11,"titulo":"Relatórios","topicos":[{"id":"11-ler-os-numeros-do-periodo","titulo":"Ler os números do período","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No menu, abra <b>Relatórios</b>.","img":"manual/img/relatorios.webp","alt":"Relatórios no celular"},{"h":"Escolha o período: <b>Hoje</b>, <b>7 dias</b>, <b>30 dias</b>, <b>Mês</b> ou <b>Personalizado</b> (neste caso, preencha <b>De</b> e <b>Até</b>)."},{"h":"Veja os cartões de indicadores: mensagens enviadas e recebidas, atendimentos, atendimentos resolvidos, falhas de envio, campanhas enviadas e tempo médio da 1ª resposta. Cada cartão mostra a variação em relação ao período anterior."},{"h":"Toque em um cartão para abrir os detalhes, com gráfico diário e tabela de valores."}]},{"t":"nota","tipo":"dica","h":"alguns cartões só aparecem quando o recurso correspondente (atendimento, campanhas) está disponível na conexão."}],"busca":"relatorios ler os numeros do periodo no menu, abra relatorios. escolha o periodo: hoje, 7 dias, 30 dias, mes ou personalizado (neste caso, preencha de e ate). veja os cartoes de indicadores: mensagens enviadas e recebidas, atendimentos, atendimentos resolvidos, falhas de envio, campanhas enviadas e tempo medio da 1ª resposta. cada cartao mostra a variacao em relacao ao periodo anterior. toque em um cartao para abrir os detalhes, com grafico diario e tabela de valores. alguns cartoes so aparecem quando o recurso correspondente (atendimento, campanhas) esta disponivel na conexao."},{"id":"11-grafico-ranking-e-horarios-de-pico","titulo":"Gráfico, ranking e horários de pico","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Em <b>Mensagens por dia</b>, alterne entre <b>barras</b> e <b>linhas</b> nos botões do canto. Azul = enviadas, verde = recebidas. A tabela abaixo traz os mesmos valores em texto."},{"h":"Em <b>Origem dos envios</b>, veja quanto saiu do Painel, Agendadas, Automações, Chatbot, Filas, Campanhas e API."},{"h":"Em <b>Ranking por usuário</b> e <b>Ranking por fila</b>, compare quem mais atendeu e o desempenho de cada fila."},{"h":"Em <b>Horários de pico</b>, toque numa célula do mapa de calor para ver quantas mensagens houve naquele dia da semana e hora.","img":"manual/img/relatorios-desktop.webp","alt":"Relatórios no computador"}]}],"busca":"relatorios grafico, ranking e horarios de pico em mensagens por dia, alterne entre barras e linhas nos botoes do canto. azul = enviadas, verde = recebidas. a tabela abaixo traz os mesmos valores em texto. em origem dos envios, veja quanto saiu do painel, agendadas, automacoes, chatbot, filas, campanhas e api. em ranking por usuario e ranking por fila, compare quem mais atendeu e o desempenho de cada fila. em horarios de pico, toque numa celula do mapa de calor para ver quantas mensagens houve naquele dia da semana e hora."},{"id":"11-exportar-relatorios-em-csv","titulo":"Exportar relatórios em CSV","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Toque em <b>Exportar CSV</b> (precisa da permissão de exportar)."},{"h":"Escolha o relatório: <b>Envios (lista completa)</b>, <b>Mensagens por dia</b>, <b>Por usuário</b>, <b>Por fila</b>, <b>Horários de pico</b> ou <b>Atendimentos</b>. O período usado é o que está selecionado na tela."},{"h":"O arquivo é baixado e abre em planilhas como Excel ou Google Planilhas."}]}],"busca":"relatorios exportar relatorios em csv toque em exportar csv (precisa da permissao de exportar). escolha o relatorio: envios (lista completa), mensagens por dia, por usuario, por fila, horarios de pico ou atendimentos. o periodo usado e o que esta selecionado na tela. o arquivo e baixado e abre em planilhas como excel ou google planilhas."}]},{"n":12,"titulo":"Histórico","topicos":[{"id":"12-consultar-e-filtrar-envios","titulo":"Consultar e filtrar envios","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No menu, abra <b>Histórico</b>.","img":"manual/img/historico.webp","alt":"Histórico de envios"},{"h":"No topo, os cartões mostram <b>Envios</b>, <b>Com sucesso</b>, <b>Com erro</b> e <b>Hoje</b>."},{"h":"Use <b>Buscar por texto, número ou erro</b> para procurar."},{"h":"Refine com os filtros: <b>Origem</b> (<b>Todos</b>, <b>Painel</b>, <b>Agenda</b>), <b>Resultado</b> (<b>Todos</b>, <b>Sucesso</b>, <b>Erro</b>) e <b>Período</b> (<b>Todo o período</b>, <b>Só hoje</b>)."},{"h":"Toque em <b>Carregar mais</b> para ver envios antigos. A lista se atualiza sozinha a cada 10 segundos (selo <b>ao vivo</b>)."}]}],"busca":"historico consultar e filtrar envios no menu, abra historico. no topo, os cartoes mostram envios, com sucesso, com erro e hoje. use buscar por texto, numero ou erro para procurar. refine com os filtros: origem (todos, painel, agenda), resultado (todos, sucesso, erro) e periodo (todo o periodo, so hoje). toque em carregar mais para ver envios antigos. a lista se atualiza sozinha a cada 10 segundos (selo ao vivo)."},{"id":"12-ver-se-a-mensagem-foi-entregue-e-lida","titulo":"Ver se a mensagem foi entregue e lida","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Em um envio com sucesso, toque em <b>Ver status</b>."},{"h":"O painel consulta o WhatsApp e mostra se a mensagem está <b>Enviando…</b>, <b>Enviada</b>, <b>Entregue</b> ou <b>Lida</b>."}]},{"t":"nota","tipo":"dica","h":"envios com erro mostram o motivo na própria linha, o que ajuda a descobrir o problema (número inválido, conexão caída etc.)."}],"busca":"historico ver se a mensagem foi entregue e lida em um envio com sucesso, toque em ver status. o painel consulta o whatsapp e mostra se a mensagem esta enviando…, enviada, entregue ou lida. envios com erro mostram o motivo na propria linha, o que ajuda a descobrir o problema (numero invalido, conexao caida etc.)."},{"id":"12-exportar-o-historico","titulo":"Exportar o histórico","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Toque em <b>Exportar CSV</b> (barra acima da lista)."},{"h":"O arquivo <code>zapzap-historico-AAAA-MM-DD.csv</code> é baixado."}]},{"t":"nota","tipo":"aviso","h":"sem a permissão de exportar, o botão aparece desativado com um cadeado."}],"busca":"historico exportar o historico toque em exportar csv (barra acima da lista). o arquivo zapzap-historico-aaaa-mm-dd.csv e baixado. sem a permissao de exportar, o botao aparece desativado com um cadeado."}]},{"n":13,"titulo":"Integrações (API e webhooks)","topicos":[{"id":"13-criar-um-token-de-api","titulo":"Criar um token de API","admin":false,"blocos":[{"t":"p","h":"O token é a &quot;chave&quot; que o outro sistema usa. Cada token vale para uma conexão e só faz o que você marcar."},{"t":"ol","itens":[{"h":"No menu, abra <b>Integrações</b> e fique na aba <b>Tokens</b>.","img":"manual/img/integracoes.webp","alt":"Integrações"},{"h":"Toque em <b>Novo token</b>."},{"h":"Preencha <b>Nome do token</b> (ex.: Meu sistema de pedidos) e escolha a <b>Conexão do WhatsApp</b>."},{"h":"Em <b>O que este token pode fazer</b>, marque os escopos: <b>Enviar texto</b>, <b>Enviar mídia</b>, <b>Ver status</b> e <b>Ler mensagens</b>."},{"h":"Defina o <b>Limite de requisições por minuto</b> (padrão 30, de 1 a 600) e a <b>Assinatura nas mensagens</b> (ex.: Loja Aurora)."},{"h":"Toque em <b>Criar token</b>.","img":"manual/img/integracao-token.webp","alt":"Token criado"},{"h":"Copie o token com <b>Copiar token</b> e guarde em local seguro. Ele aparece uma única vez; depois só fica visível o início dele."}]},{"t":"nota","tipo":"aviso","h":"toda mensagem enviada pela API sai assinada, na primeira linha, em negrito (por exemplo <code>*Loja Aurora:*</code>). Não dá para desligar."}],"busca":"integracoes (api e webhooks) criar um token de api o token e a \"chave\" que o outro sistema usa. cada token vale para uma conexao e so faz o que voce marcar. no menu, abra integracoes e fique na aba tokens. toque em novo token. preencha nome do token (ex.: meu sistema de pedidos) e escolha a conexao do whatsapp. em o que este token pode fazer, marque os escopos: enviar texto, enviar midia, ver status e ler mensagens. defina o limite de requisicoes por minuto (padrao 30, de 1 a 600) e a assinatura nas mensagens (ex.: loja aurora). toque em criar token. copie o token com copiar token e guarde em local seguro. ele aparece uma unica vez; depois so fica visivel o inicio dele. toda mensagem enviada pela api sai assinada, na primeira linha, em negrito (por exemplo *loja aurora:*). nao da para desligar."},{"id":"13-acompanhar-o-uso-e-revogar-um-token","titulo":"Acompanhar o uso e revogar um token","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Na aba <b>Tokens</b>, cada cartão mostra a conexão, os escopos, a assinatura, o limite por minuto, o último uso e a quantidade de usos."},{"h":"Toque em <b>Uso</b> para ver as chamadas recentes."},{"h":"Se o token vazou ou não é mais necessário, toque em <b>Revogar</b>. Ele deixa de funcionar na hora."}]}],"busca":"integracoes (api e webhooks) acompanhar o uso e revogar um token na aba tokens, cada cartao mostra a conexao, os escopos, a assinatura, o limite por minuto, o ultimo uso e a quantidade de usos. toque em uso para ver as chamadas recentes. se o token vazou ou nao e mais necessario, toque em revogar. ele deixa de funcionar na hora."},{"id":"13-chamar-a-api-publica","titulo":"Chamar a API pública","admin":false,"blocos":[{"t":"p","h":"A URL base é <code>https://SEU-DOMINIO/zapzap/api_publica.php?acao=…</code>. Envie o token no cabeçalho <code>X-API-Token</code> (ou <code>Authorization: Bearer</code>). As respostas são sempre JSON, com <code>{&quot;ok&quot;: false, &quot;msg&quot;: &quot;...&quot;}</code> quando há erro. Se passar do limite por minuto, a API responde HTTP 429 e informa em quantos segundos tentar de novo."},{"t":"p","h":"Enviar texto (escopo &quot;Enviar texto&quot;; de 1 a 4000 caracteres):"},{"t":"cod","c":"curl -X POST \"https://SEU-DOMINIO/zapzap/api_publica.php?acao=enviar_texto\" \\\n  -H \"X-API-Token: zz_SEU_TOKEN_AQUI\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"numero\":\"5582999990001\",\"texto\":\"Olá! Pedido confirmado.\"}'"},{"t":"p","h":"Use o número só com dígitos, com DDI e DDD, por exemplo <code>5582999990001</code>. Resposta de sucesso: <code>{&quot;ok&quot;:true,&quot;msg_id&quot;:&quot;...&quot;,&quot;numero&quot;:&quot;...&quot;}</code>."},{"t":"p","h":"Enviar mídia (escopo &quot;Enviar mídia&quot;): informe <code>numero</code>, <code>mime</code>, <code>nome</code> e <b>uma</b> das opções <code>url</code> (https público) ou <code>base64</code>. A legenda é opcional (até 1000 caracteres) e o arquivo pode ter até 25 MB."},{"t":"cod","c":"curl -X POST \"https://SEU-DOMINIO/zapzap/api_publica.php?acao=enviar_midia\" \\\n  -H \"X-API-Token: zz_SEU_TOKEN_AQUI\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"numero\":\"5582999990001\",\"url\":\"https://exemplo.com/foto.jpg\",\"mime\":\"image/jpeg\",\"nome\":\"foto.jpg\",\"legenda\":\"Olha só\"}'"},{"t":"p","h":"Ver se o WhatsApp está conectado (escopo &quot;Ver status&quot;):"},{"t":"cod","c":"curl -H \"X-API-Token: zz_SEU_TOKEN_AQUI\" \\\n  \"https://SEU-DOMINIO/zapzap/api_publica.php?acao=status\""},{"t":"p","h":"Listar mensagens de uma conversa (escopo &quot;Ler mensagens&quot;; <code>limite</code> de 1 a 50, padrão 20):"},{"t":"cod","c":"curl -H \"X-API-Token: zz_SEU_TOKEN_AQUI\" \\\n  \"https://SEU-DOMINIO/zapzap/api_publica.php?acao=mensagens&jid=5582999990001&limite=10\""},{"t":"nota","tipo":"dica","h":"abra <code>?acao=ajuda</code> (sem token) para ler a documentação resumida da API, e use a aba <b>Como usar</b> do painel para copiar exemplos em cURL, PHP e JavaScript."}],"busca":"integracoes (api e webhooks) chamar a api publica a url base e https://seu-dominio/zapzap/api_publica.php?acao=…. envie o token no cabecalho x-api-token (ou authorization: bearer). as respostas sao sempre json, com {\"ok\": false, \"msg\": \"...\"} quando ha erro. se passar do limite por minuto, a api responde http 429 e informa em quantos segundos tentar de novo. enviar texto (escopo \"enviar texto\"; de 1 a 4000 caracteres):  use o numero so com digitos, com ddi e ddd, por exemplo 5582999990001. resposta de sucesso: {\"ok\":true,\"msg_id\":\"...\",\"numero\":\"...\"}. enviar midia (escopo \"enviar midia\"): informe numero, mime, nome e uma das opcoes url (https publico) ou base64. a legenda e opcional (ate 1000 caracteres) e o arquivo pode ter ate 25 mb.  ver se o whatsapp esta conectado (escopo \"ver status\"):  listar mensagens de uma conversa (escopo \"ler mensagens\"; limite de 1 a 50, padrao 20):  abra ?acao=ajuda (sem token) para ler a documentacao resumida da api, e use a aba como usar do painel para copiar exemplos em curl, php e javascript."},{"id":"13-receber-avisos-com-webhooks-de-saida","titulo":"Receber avisos com webhooks de saída","admin":false,"blocos":[{"t":"p","h":"Webhooks fazem o caminho inverso: o ZapZap avisa o seu sistema quando algo acontece."},{"t":"ol","itens":[{"h":"Em <b>Integrações</b>, toque na aba <b>Webhooks</b> e em <b>Novo webhook</b>.","img":"manual/img/integracao-webhooks.webp","alt":"Webhooks de saída"},{"h":"Preencha <b>Nome</b> e <b>URL que vai receber os avisos (https)</b>. Só endereços https públicos são aceitos; endereços internos são recusados."},{"h":"Marque os <b>Eventos</b>: <b>Mensagem recebida</b>, <b>Mensagem enviada</b> e <b>Mudança de conexão</b>."},{"h":"Deixe <b>Ligado</b> marcado (desligue para pausar sem excluir) e toque em <b>Salvar</b>."},{"h":"O <b>segredo</b> do webhook é mostrado uma única vez; copie com <b>Copiar segredo</b>. Use-o para conferir a assinatura <code>X-ZapZap-Assinatura</code> (HMAC-SHA256 do corpo) em cada aviso recebido."},{"h":"Toque em <b>Testar</b> para enviar um aviso de teste e ver o resultado (código HTTP e tempo). Em <b>Logs</b> você vê as entregas, com número de tentativas (o painel tenta até 2 vezes, 5 segundos cada)."}]},{"t":"p","h":"O aviso chega como JSON no formato <code>{&quot;evento&quot;:&quot;mensagem_recebida&quot;,&quot;instancia&quot;:&quot;...&quot;,&quot;ts&quot;:1790000000,&quot;teste&quot;:false,&quot;dados&quot;:{...}}</code>, com os cabeçalhos <code>X-ZapZap-Evento</code> e <code>X-ZapZap-Assinatura</code>."},{"t":"nota","tipo":"dica","h":"ao editar um webhook, marque <b>Gerar novo segredo</b> se quiser trocar o segredo; o antigo deixa de valer."}],"busca":"integracoes (api e webhooks) receber avisos com webhooks de saida webhooks fazem o caminho inverso: o zapzap avisa o seu sistema quando algo acontece. em integracoes, toque na aba webhooks e em novo webhook. preencha nome e url que vai receber os avisos (https). so enderecos https publicos sao aceitos; enderecos internos sao recusados. marque os eventos: mensagem recebida, mensagem enviada e mudanca de conexao. deixe ligado marcado (desligue para pausar sem excluir) e toque em salvar. o segredo do webhook e mostrado uma unica vez; copie com copiar segredo. use-o para conferir a assinatura x-zapzap-assinatura (hmac-sha256 do corpo) em cada aviso recebido. toque em testar para enviar um aviso de teste e ver o resultado (codigo http e tempo). em logs voce ve as entregas, com numero de tentativas (o painel tenta ate 2 vezes, 5 segundos cada). o aviso chega como json no formato {\"evento\":\"mensagem_recebida\",\"instancia\":\"...\",\"ts\":1790000000,\"teste\":false,\"dados\":{...}}, com os cabecalhos x-zapzap-evento e x-zapzap-assinatura. ao editar um webhook, marque gerar novo segredo se quiser trocar o segredo; o antigo deixa de valer."}]},{"n":14,"titulo":"Usuários e permissões","topicos":[{"id":"14-criar-um-usuario","titulo":"Criar um usuário","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No menu, abra <b>Usuários</b>.","img":"manual/img/usuarios.webp","alt":"Lista de usuários"},{"h":"Toque em <b>Novo usuário</b>. Use <b>Buscar por nome ou usuário</b> para achar alguém depois."},{"h":"Preencha <b>Nome (aparece nas mensagens enviadas)</b>, <b>Usuário (login)</b> e <b>Senha</b> (mínimo de 6 caracteres).","img":"manual/img/usuario-editor.webp","alt":"Editor de usuário com permissões"},{"h":"Escolha as permissões (veja o próximo tópico) e as conexões liberadas."},{"h":"Toque em <b>Salvar</b>. O botão só fica ativo quando há alterações; se tentar sair sem salvar, o painel pergunta se deseja descartar."}]},{"t":"nota","tipo":"aviso","h":"o nome do usuário é usado na assinatura de toda mensagem que ele enviar (<code>*Nome:*</code> na primeira linha). Escolha um nome que o cliente reconheça."}],"busca":"usuarios e permissoes criar um usuario no menu, abra usuarios. toque em novo usuario. use buscar por nome ou usuario para achar alguem depois. preencha nome (aparece nas mensagens enviadas), usuario (login) e senha (minimo de 6 caracteres). escolha as permissoes (veja o proximo topico) e as conexoes liberadas. toque em salvar. o botao so fica ativo quando ha alteracoes; se tentar sair sem salvar, o painel pergunta se deseja descartar. o nome do usuario e usado na assinatura de toda mensagem que ele enviar (*nome:* na primeira linha). escolha um nome que o cliente reconheca."},{"id":"14-usar-perfis-rapidos-e-ajustar-permissoes","titulo":"Usar perfis rápidos e ajustar permissões","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No editor, em <b>Permissões</b>, toque em um perfil rápido para marcar várias permissões de uma vez:<br>- <b>Atendente</b>: conversas, envio de texto e mídia, respostas, filas, etiquetas e notas.<br>- <b>Somente leitura</b>: só visualiza telas.<br>- <b>Gerente</b>: quase tudo, exceto criar/excluir/desconectar conexões, API e reiniciar."},{"h":"Depois ajuste item a item. As permissões são agrupadas (Conversas, Enviar, Agendadas, Contatos, Grupos, Histórico, Conexões, Configurações, Automações, Chatbot, Filas e atendimento, Campanhas, Respostas rápidas, Etiquetas e notas, Relatórios, Integrações, Auditoria, Versões). Cada grupo tem <b>Marcar tudo</b> e <b>Limpar</b>; no topo há <b>Marcar tudo</b> e <b>Limpar</b> gerais."},{"h":"O contador mostra quantas permissões estão liberadas."}]},{"t":"nota","tipo":"dica","h":"um usuário master tem acesso total e não tem permissões para ajustar."}],"busca":"usuarios e permissoes usar perfis rapidos e ajustar permissoes no editor, em permissoes, toque em um perfil rapido para marcar varias permissoes de uma vez:- atendente: conversas, envio de texto e midia, respostas, filas, etiquetas e notas.- somente leitura: so visualiza telas.- gerente: quase tudo, exceto criar/excluir/desconectar conexoes, api e reiniciar. depois ajuste item a item. as permissoes sao agrupadas (conversas, enviar, agendadas, contatos, grupos, historico, conexoes, configuracoes, automacoes, chatbot, filas e atendimento, campanhas, respostas rapidas, etiquetas e notas, relatorios, integracoes, auditoria, versoes). cada grupo tem marcar tudo e limpar; no topo ha marcar tudo e limpar gerais. o contador mostra quantas permissoes estao liberadas. um usuario master tem acesso total e nao tem permissoes para ajustar."},{"id":"14-liberar-conexoes","titulo":"Liberar conexões","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No editor, na seção <b>Conexões liberadas</b>, marque <b>Todas as conexões</b> (inclusive as criadas depois) ou escolha uma a uma as que o usuário pode ver."},{"h":"É obrigatório escolher ao menos uma conexão (ou marcar <b>Todas</b>)."}]},{"t":"nota","tipo":"aviso","h":"o usuário só enxerga conversas, contatos e relatórios das conexões liberadas."}],"busca":"usuarios e permissoes liberar conexoes no editor, na secao conexoes liberadas, marque todas as conexoes (inclusive as criadas depois) ou escolha uma a uma as que o usuario pode ver. e obrigatorio escolher ao menos uma conexao (ou marcar todas). o usuario so enxerga conversas, contatos e relatorios das conexoes liberadas."},{"id":"14-gerar-ou-redefinir-a-senha-de-um-usuario","titulo":"Gerar ou redefinir a senha de um usuário","admin":false,"blocos":[{"t":"p","h":"Por segurança, ninguém consegue ler a senha de outro usuário. A senha que você cria ou gera é definitiva; ela só aparece uma vez para você repassar."},{"t":"ol","itens":[{"h":"Em <b>Usuários</b>, toque no usuário para abrir o detalhe."},{"h":"Toque em <b>Gerar nova senha</b> e confirme: o painel cria uma senha aleatória.","img":"manual/img/usuario-senha.webp","alt":"Nova senha mostrada uma única vez"},{"h":"Copie com <b>Copiar senha</b> ou <b>Copiar login + senha</b> e envie à pessoa por um canal seguro."},{"h":"A senha só aparece agora. A senha antiga deixa de funcionar e as sessões abertas são encerradas."},{"h":"Se preferir escolher você mesmo a senha, toque em <b>Redefinir senha</b> e digite a <b>Nova senha</b> (mínimo 6 caracteres)."}]},{"t":"nota","tipo":"dica","h":"nas duas telas (e ao criar o usuário) existe a opção <b>Exigir que a pessoa troque a senha no primeiro acesso</b>. Ela vem desligada; ligue só se quiser que a pessoa crie uma senha própria na primeira entrada."}],"busca":"usuarios e permissoes gerar ou redefinir a senha de um usuario por seguranca, ninguem consegue ler a senha de outro usuario. a senha que voce cria ou gera e definitiva; ela so aparece uma vez para voce repassar. em usuarios, toque no usuario para abrir o detalhe. toque em gerar nova senha e confirme: o painel cria uma senha aleatoria. copie com copiar senha ou copiar login + senha e envie a pessoa por um canal seguro. a senha so aparece agora. a senha antiga deixa de funcionar e as sessoes abertas sao encerradas. se preferir escolher voce mesmo a senha, toque em redefinir senha e digite a nova senha (minimo 6 caracteres). nas duas telas (e ao criar o usuario) existe a opcao exigir que a pessoa troque a senha no primeiro acesso. ela vem desligada; ligue so se quiser que a pessoa crie uma senha propria na primeira entrada."},{"id":"14-ver-a-atividade-e-as-sessoes-de-um-usuario","titulo":"Ver a atividade e as sessões de um usuário","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No detalhe do usuário há três abas: <b>Atividade</b>, <b>Sessões</b> e <b>Permissões</b>."},{"h":"Em <b>Atividade</b>, veja o que a pessoa fez. Os cartões <b>Hoje</b>, <b>7 dias</b> e <b>Último acesso</b> funcionam como filtros; também há busca, período (<b>Todo o período</b>, <b>Hoje</b>, <b>Últimos 7 dias</b>, <b>Últimos 30 dias</b> ou datas escolhidas), tipo de ação e <b>Exportar CSV</b>.","img":"manual/img/usuario-atividade.webp","alt":"Atividade do usuário"},{"h":"Em <b>Sessões</b>, veja onde a pessoa está conectada. <b>Encerrar todas</b> faz com que ela precise entrar de novo."},{"h":"Em <b>Permissões</b>, veja as conexões liberadas e as permissões ativas."}]}],"busca":"usuarios e permissoes ver a atividade e as sessoes de um usuario no detalhe do usuario ha tres abas: atividade, sessoes e permissoes. em atividade, veja o que a pessoa fez. os cartoes hoje, 7 dias e ultimo acesso funcionam como filtros; tambem ha busca, periodo (todo o periodo, hoje, ultimos 7 dias, ultimos 30 dias ou datas escolhidas), tipo de acao e exportar csv. em sessoes, veja onde a pessoa esta conectada. encerrar todas faz com que ela precise entrar de novo. em permissoes, veja as conexoes liberadas e as permissoes ativas."},{"id":"14-desativar-ou-excluir-um-usuario","titulo":"Desativar ou excluir um usuário","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No detalhe, toque em <b>Desativar</b> para impedir o acesso sem apagar nada (as sessões abertas são encerradas). <b>Ativar</b> reverte."},{"h":"Para apagar de vez, toque em <b>Excluir</b>, digite o texto de confirmação pedido e confirme de novo. O histórico de atividade pode ser mantido para auditoria."}]},{"t":"nota","tipo":"aviso","h":"você não pode desativar nem excluir a si mesmo."}],"busca":"usuarios e permissoes desativar ou excluir um usuario no detalhe, toque em desativar para impedir o acesso sem apagar nada (as sessoes abertas sao encerradas). ativar reverte. para apagar de vez, toque em excluir, digite o texto de confirmacao pedido e confirme de novo. o historico de atividade pode ser mantido para auditoria. voce nao pode desativar nem excluir a si mesmo."}]},{"n":15,"titulo":"Auditoria","topicos":[{"id":"15-consultar-o-registro-de-atividades","titulo":"Consultar o registro de atividades","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No menu, abra <b>Auditoria</b>.","img":"manual/img/auditoria.webp","alt":"Auditoria"},{"h":"Os cartões no topo resumem por tipo: <b>Acessos</b>, <b>Envios</b>, <b>Configuração</b>, <b>Usuários</b>, <b>Conexões</b> e <b>Navegação</b>. Toque num cartão para filtrar."},{"h":"Use <b>Buscar por usuário, IP ou detalhe</b> e as pílulas de tipo e de período (<b>Hoje</b>, <b>7 dias</b>, <b>30 dias</b>, <b>Tudo</b>, <b>Período…</b> com <b>De</b> e <b>Até</b>)."},{"h":"O administrador também pode filtrar por usuário. <b>Falhas</b> mostra só o que deu errado e <b>Limpar filtros</b> volta ao início."},{"h":"Cada linha mostra a ação, o usuário, o IP, a conexão, se deu certo e um detalhe curto. O conteúdo das mensagens e as senhas nunca são gravados."},{"h":"Toque em <b>Exportar CSV</b> para baixar o registro filtrado."}]}],"busca":"auditoria consultar o registro de atividades no menu, abra auditoria. os cartoes no topo resumem por tipo: acessos, envios, configuracao, usuarios, conexoes e navegacao. toque num cartao para filtrar. use buscar por usuario, ip ou detalhe e as pilulas de tipo e de periodo (hoje, 7 dias, 30 dias, tudo, periodo… com de e ate). o administrador tambem pode filtrar por usuario. falhas mostra so o que deu errado e limpar filtros volta ao inicio. cada linha mostra a acao, o usuario, o ip, a conexao, se deu certo e um detalhe curto. o conteudo das mensagens e as senhas nunca sao gravados. toque em exportar csv para baixar o registro filtrado."},{"id":"15-entender-o-alerta-de-falhas-de-login","titulo":"Entender o alerta de falhas de login","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Quando há várias tentativas de login falhas vindas do mesmo IP na última hora, aparece o aviso <b>Atenção: falhas de login repetidas</b>, com o IP e a hora da última tentativa."},{"h":"Se o aviso for inesperado, troque as senhas dos usuários e gere novas senhas em <b>Usuários</b>."}]},{"t":"nota","tipo":"dica","h":"o próprio sistema bloqueia tentativas em excesso: depois de várias falhas seguidas o login fica indisponível por cerca de 15 minutos."}],"busca":"auditoria entender o alerta de falhas de login quando ha varias tentativas de login falhas vindas do mesmo ip na ultima hora, aparece o aviso atencao: falhas de login repetidas, com o ip e a hora da ultima tentativa. se o aviso for inesperado, troque as senhas dos usuarios e gere novas senhas em usuarios. o proprio sistema bloqueia tentativas em excesso: depois de varias falhas seguidas o login fica indisponivel por cerca de 15 minutos."}]},{"n":16,"titulo":"Configurações","topicos":[{"id":"16-ajustar-o-comportamento-da-conexao","titulo":"Ajustar o comportamento da conexão","admin":false,"blocos":[{"t":"ol","itens":[{"h":"No menu, abra <b>Configurações</b>.","img":"manual/img/config.webp","alt":"Configurações"},{"h":"Em <b>Comportamento</b>, ligue ou desligue: <b>Rejeitar chamadas</b>, <b>Ignorar grupos</b>, <b>Sempre online</b>, <b>Marcar mensagens como lidas</b>, <b>Ver status dos contatos</b> e <b>Sincronizar histórico completo</b>."},{"h":"Ao ligar <b>Rejeitar chamadas</b>, preencha a <b>Mensagem enviada a quem ligar</b>."},{"h":"Toque em <b>Salvar comportamento</b> (o botão só ativa depois de uma mudança)."}]},{"t":"nota","tipo":"aviso","h":"a conexão também pode ser usada por outro sistema ligado ao mesmo WhatsApp. As mudanças valem para todos que a usam."}],"busca":"configuracoes ajustar o comportamento da conexao no menu, abra configuracoes. em comportamento, ligue ou desligue: rejeitar chamadas, ignorar grupos, sempre online, marcar mensagens como lidas, ver status dos contatos e sincronizar historico completo. ao ligar rejeitar chamadas, preencha a mensagem enviada a quem ligar. toque em salvar comportamento (o botao so ativa depois de uma mudanca). a conexao tambem pode ser usada por outro sistema ligado ao mesmo whatsapp. as mudancas valem para todos que a usam."},{"id":"16-mudar-o-nome-e-o-recado-do-perfil","titulo":"Mudar o nome e o recado do perfil","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Em <b>Perfil</b>, edite <b>Nome do perfil</b> (até 25 caracteres) e toque em <b>Salvar</b>."},{"h":"Edite o <b>Recado (status)</b> (até 139 caracteres) e toque no <b>Salvar</b> correspondente."}]},{"t":"nota","tipo":"dica","h":"exige a permissão de alterar o perfil; sem ela, os campos ficam bloqueados com um cadeado."}],"busca":"configuracoes mudar o nome e o recado do perfil em perfil, edite nome do perfil (ate 25 caracteres) e toque em salvar. edite o recado (status) (ate 139 caracteres) e toque no salvar correspondente. exige a permissao de alterar o perfil; sem ela, os campos ficam bloqueados com um cadeado."},{"id":"16-trocar-a-sua-senha","titulo":"Trocar a sua senha","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Em <b>Segurança</b>, digite a <b>Senha atual</b>.","img":"manual/img/config-senha.webp","alt":"Trocar senha"},{"h":"Digite a <b>Nova senha</b> (mínimo de 6 caracteres, diferente da atual) e repita em <b>Repetir nova senha</b>. O olho mostra ou oculta o texto."},{"h":"Toque em <b>Trocar senha</b>."},{"h":"As sessões abertas em outros aparelhos são encerradas; a atual continua."}]}],"busca":"configuracoes trocar a sua senha em seguranca, digite a senha atual. digite a nova senha (minimo de 6 caracteres, diferente da atual) e repita em repetir nova senha. o olho mostra ou oculta o texto. toque em trocar senha. as sessoes abertas em outros aparelhos sao encerradas; a atual continua."},{"id":"16-instalar-o-app-e-forcar-atualizacao","titulo":"Instalar o app e forçar atualização","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Em <b>Sobre</b>, veja a versão do painel e da Evolution API."},{"h":"Toque em <b>Instalar aplicativo</b> para ver como adicionar o ZapZap à tela inicial."},{"h":"Se algo parecer desatualizado, toque em <b>Forçar atualização agora</b>: o painel limpa o cache e recarrega."}]}],"busca":"configuracoes instalar o app e forcar atualizacao em sobre, veja a versao do painel e da evolution api. toque em instalar aplicativo para ver como adicionar o zapzap a tela inicial. se algo parecer desatualizado, toque em forcar atualizacao agora: o painel limpa o cache e recarrega."},{"id":"16-reiniciar-a-conexao","titulo":"Reiniciar a conexão","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Em <b>Conexão</b>, se o WhatsApp estiver desconectado, toque em <b>Gerar QR Code</b> e leia pelo celular (WhatsApp, Configurações, Aparelhos conectados, <b>Conectar um aparelho</b>)."},{"h":"<b>Reiniciar conexão</b> exige confirmação dupla, porque o WhatsApp fica fora do ar por alguns segundos."}]},{"t":"nota","tipo":"aviso","h":"sair da conta (botão <b>Sair</b> em <b>Minha conta</b>) encerra apenas a sessão do painel; não desconecta o WhatsApp."}],"busca":"configuracoes reiniciar a conexao em conexao, se o whatsapp estiver desconectado, toque em gerar qr code e leia pelo celular (whatsapp, configuracoes, aparelhos conectados, conectar um aparelho). reiniciar conexao exige confirmacao dupla, porque o whatsapp fica fora do ar por alguns segundos. sair da conta (botao sair em minha conta) encerra apenas a sessao do painel; nao desconecta o whatsapp."},{"id":"16-consultar-o-historico-de-versoes","titulo":"Consultar o histórico de versões","admin":true,"blocos":[{"t":"p","h":"A tela <b>Versões</b> só aparece para o administrador (master). Ela também abre ao tocar na versão no rodapé do menu lateral."},{"t":"ol","itens":[{"h":"Abra <b>Versões</b> pelo menu lateral.","img":"manual/img/versoes.webp","alt":"Histórico de versões"},{"h":"Cada cartão mostra o número da versão (a atual traz o selo <b>atual</b>), a data, o título e a lista do que mudou."},{"h":"Toque em &quot;arquivo(s) alterado(s)&quot; para ver quais arquivos foram modificados."}]}],"busca":"configuracoes consultar o historico de versoes a tela versoes so aparece para o administrador (master). ela tambem abre ao tocar na versao no rodape do menu lateral. abra versoes pelo menu lateral. cada cartao mostra o numero da versao (a atual traz o selo atual), a data, o titulo e a lista do que mudou. toque em \"arquivo(s) alterado(s)\" para ver quais arquivos foram modificados."}]},{"n":17,"titulo":"Dúvidas frequentes e solução de problemas","topicos":[{"id":"17-o-qr-code-nao-aparece-ou-expirou","titulo":"O QR Code não aparece ou expirou","admin":false,"blocos":[{"t":"p","h":"O QR só é gerado quando a conexão não está conectada, e vale por pouco tempo."},{"t":"ol","itens":[{"h":"Abra <b>Conexões</b> (ou <b>Configurações</b>, na seção <b>Conexão</b>) e toque em <b>Conectar / Gerar QR</b> ou <b>Gerar QR Code</b>."},{"h":"Se o QR expirar, gere outro."},{"h":"No celular: WhatsApp, <b>Configurações</b>, <b>Aparelhos conectados</b>, <b>Conectar um aparelho</b>."},{"h":"Se continuar sem aparecer, toque em <b>Tentar de novo</b>. Se a conexão já estiver conectada, o QR não é gerado."}]},{"t":"nota","tipo":"dica","h":"é preciso ter a permissão de gerar QR Code."}],"busca":"duvidas frequentes e solucao de problemas o qr code nao aparece ou expirou o qr so e gerado quando a conexao nao esta conectada, e vale por pouco tempo. abra conexoes (ou configuracoes, na secao conexao) e toque em conectar / gerar qr ou gerar qr code. se o qr expirar, gere outro. no celular: whatsapp, configuracoes, aparelhos conectados, conectar um aparelho. se continuar sem aparecer, toque em tentar de novo. se a conexao ja estiver conectada, o qr nao e gerado. e preciso ter a permissao de gerar qr code."},{"id":"17-a-mensagem-nao-chega-ao-destinatario","titulo":"A mensagem não chega ao destinatário","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Em <b>Histórico</b>, procure o envio e veja se está com <b>Sucesso</b> ou <b>Erro</b>; o motivo aparece na linha."},{"h":"Toque em <b>Ver status</b> para saber se está <b>Enviada</b>, <b>Entregue</b> ou <b>Lida</b>. &quot;Enviada&quot; sem &quot;Entregue&quot; costuma significar que o celular da pessoa está desligado ou sem internet."},{"h":"Confira se a conexão está <b>WhatsApp conectado</b> (selo no topo da tela)."},{"h":"Em <b>Contatos</b>, use <b>Verificar número</b> para ver se o número tem WhatsApp."}]}],"busca":"duvidas frequentes e solucao de problemas a mensagem nao chega ao destinatario em historico, procure o envio e veja se esta com sucesso ou erro; o motivo aparece na linha. toque em ver status para saber se esta enviada, entregue ou lida. \"enviada\" sem \"entregue\" costuma significar que o celular da pessoa esta desligado ou sem internet. confira se a conexao esta whatsapp conectado (selo no topo da tela). em contatos, use verificar numero para ver se o numero tem whatsapp."},{"id":"17-o-numero-nao-tem-o-nono-digito","titulo":"O número não tem o nono dígito","admin":false,"blocos":[{"t":"p","h":"Em alguns números do Brasil o WhatsApp registra a conta sem o 9 extra. Você não precisa se preocupar: digite o número normalmente, com o 9. O sistema pergunta ao WhatsApp qual é o endereço real e usa o correto."},{"t":"ol","itens":[{"h":"Digite o número com DDD, como <code>82 99999-0001</code>."},{"h":"Use <b>Verificar número</b> para confirmar se existe."},{"h":"Para responder, use sempre a conversa existente em <b>Conversas</b>."}]}],"busca":"duvidas frequentes e solucao de problemas o numero nao tem o nono digito em alguns numeros do brasil o whatsapp registra a conta sem o 9 extra. voce nao precisa se preocupar: digite o numero normalmente, com o 9. o sistema pergunta ao whatsapp qual e o endereco real e usa o correto. digite o numero com ddd, como 82 99999-0001. use verificar numero para confirmar se existe. para responder, use sempre a conversa existente em conversas."},{"id":"17-aparece-sem-permissao-ou-falta-uma-tela-no-menu","titulo":"Aparece \"sem permissão\" ou falta uma tela no menu","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Telas sem permissão não aparecem no menu. Se uma ação mostra a mensagem de falta de permissão, o seu usuário não pode usá-la."},{"h":"Peça ao administrador para liberar a permissão em <b>Usuários</b>, no editor do seu usuário."},{"h":"Se aparecer &quot;Nenhuma conexão (WhatsApp) liberada para o seu usuário&quot;, falta liberar uma conexão em <b>Conexões liberadas</b>."}]}],"busca":"duvidas frequentes e solucao de problemas aparece \"sem permissao\" ou falta uma tela no menu telas sem permissao nao aparecem no menu. se uma acao mostra a mensagem de falta de permissao, o seu usuario nao pode usa-la. peca ao administrador para liberar a permissao em usuarios, no editor do seu usuario. se aparecer \"nenhuma conexao (whatsapp) liberada para o seu usuario\", falta liberar uma conexao em conexoes liberadas."},{"id":"17-esqueci-a-minha-senha","titulo":"Esqueci a minha senha","admin":false,"blocos":[{"t":"ol","itens":[{"h":"O painel não envia e-mail de recuperação. Peça ao administrador."},{"h":"Ele abre <b>Usuários</b>, toca no seu usuário e em <b>Gerar nova senha</b> (ou <b>Redefinir senha</b>)."},{"h":"Entre com a senha nova. Se ele tiver marcado a opção de exigir troca, o painel pede que você crie uma senha própria na hora; se não, é só continuar e, se quiser, trocar depois em <b>Configurações</b>."}]},{"t":"nota","tipo":"aviso","h":"depois de muitas tentativas erradas o login é bloqueado por cerca de 15 minutos (&quot;Muitas tentativas. Aguarde…&quot;). Espere e tente de novo."}],"busca":"duvidas frequentes e solucao de problemas esqueci a minha senha o painel nao envia e-mail de recuperacao. peca ao administrador. ele abre usuarios, toca no seu usuario e em gerar nova senha (ou redefinir senha). entre com a senha nova. se ele tiver marcado a opcao de exigir troca, o painel pede que voce crie uma senha propria na hora; se nao, e so continuar e, se quiser, trocar depois em configuracoes. depois de muitas tentativas erradas o login e bloqueado por cerca de 15 minutos (\"muitas tentativas. aguarde…\"). espere e tente de novo."},{"id":"17-nao-escuto-o-som-das-notificacoes-no-iphone","titulo":"Não escuto o som das notificações no iPhone","admin":false,"blocos":[{"t":"ol","itens":[{"h":"Toque no sino, no topo, e depois no ícone de ajustes (<b>Preferências</b>)."},{"h":"Confira se <b>Som</b> está ligado, o volume e o tom; toque em <b>Testar</b>."},{"h":"No iPhone o som segue a chave de silencioso do aparelho, e o navegador não libera vibração. Tire o aparelho do silencioso."},{"h":"Confira também se <b>Não perturbe</b> está ligado e quais tipos de aviso estão marcados em <b>Avisar sobre</b>."},{"h":"Instalar o ZapZap na tela inicial (Compartilhar, <b>Adicionar à Tela de Início</b>) melhora o comportamento do app."}]}],"busca":"duvidas frequentes e solucao de problemas nao escuto o som das notificacoes no iphone toque no sino, no topo, e depois no icone de ajustes (preferencias). confira se som esta ligado, o volume e o tom; toque em testar. no iphone o som segue a chave de silencioso do aparelho, e o navegador nao libera vibracao. tire o aparelho do silencioso. confira tambem se nao perturbe esta ligado e quais tipos de aviso estao marcados em avisar sobre. instalar o zapzap na tela inicial (compartilhar, adicionar a tela de inicio) melhora o comportamento do app."},{"id":"17-o-painel-pediu-para-atualizar-sozinho","titulo":"O painel pediu para atualizar sozinho","admin":false,"blocos":[{"t":"p","h":"Toda vez que uma nova versão é publicada, o painel detecta e atualiza sozinho: aparece o aviso &quot;Atualizando…&quot; e a página recarrega em instantes. Nada precisa ser feito. Se ficar preso numa versão antiga, vá em <b>Configurações</b>, <b>Sobre</b>, <b>Forçar atualização agora</b>."}],"busca":"duvidas frequentes e solucao de problemas o painel pediu para atualizar sozinho toda vez que uma nova versao e publicada, o painel detecta e atualiza sozinho: aparece o aviso \"atualizando…\" e a pagina recarrega em instantes. nada precisa ser feito. se ficar preso numa versao antiga, va em configuracoes, sobre, forcar atualizacao agora."},{"id":"17-desconectei-sem-querer-ou-a-conexao-ficou-vermelha","titulo":"Desconectei sem querer ou a conexão ficou vermelha","admin":false,"blocos":[{"t":"ol","itens":[{"h":"O selo no topo mostra <b>Desconectado</b> quando o WhatsApp está fora do ar."},{"h":"Abra <b>Conexões</b> ou <b>Configurações</b>, gere um novo QR Code e leia pelo celular."},{"h":"Se o WhatsApp voltou a conectar, o selo volta a ficar verde."}]}],"busca":"duvidas frequentes e solucao de problemas desconectei sem querer ou a conexao ficou vermelha o selo no topo mostra desconectado quando o whatsapp esta fora do ar. abra conexoes ou configuracoes, gere um novo qr code e leia pelo celular. se o whatsapp voltou a conectar, o selo volta a ficar verde."}]},{"n":18,"titulo":"Glossário","topicos":[{"id":"18-glossario","titulo":"Glossário","admin":false,"blocos":[{"t":"ul","itens":["<b>Administrador (master):</b> usuário com acesso total, inclusive a Usuários, Auditoria e Versões.","<b>API pública:</b> forma de outros sistemas enviarem mensagens e consultarem o WhatsApp usando um token.","<b>Assinatura:</b> nome em negrito na primeira linha de toda mensagem enviada por um usuário ou token (<code>*Nome:*</code>).","<b>Atendimento:</b> conversa em fila, que pode estar aguardando, em atendimento ou resolvida.","<b>Auditoria:</b> registro de quem fez o quê, quando e de onde.","<b>Conexão:</b> um número de WhatsApp ligado ao painel. Também chamada de instância.","<b>CSV:</b> arquivo de planilha simples, que abre no Excel ou Google Planilhas.","<b>Escopo:</b> permissão de um token de API (enviar texto, enviar mídia, ver status, ler mensagens).","<b>Etiqueta:</b> marcador colorido aplicado a conversas.","<b>JID:</b> identificador interno de uma conversa no WhatsApp (número ou grupo).","<b>Nota interna:</b> anotação da equipe sobre um contato; o contato nunca a recebe.","<b>Permissão:</b> autorização individual de um usuário para uma ação ou tela.","<b>Perfil rápido:</b> conjunto de permissões pronto (Atendente, Somente leitura, Gerente).","<b>QR Code:</b> imagem que o WhatsApp do celular lê para conectar o número ao painel.","<b>Resposta rápida:</b> texto pronto, chamado por um atalho com <code>/</code>.","<b>Segredo (webhook):</b> código usado para conferir que um aviso veio mesmo do ZapZap.","<b>Sessão:</b> acesso aberto de um usuário em um aparelho. Dura até 30 dias ou até ser encerrada.","<b>Token:</b> chave de acesso da API pública, mostrada uma única vez ao ser criada.","<b>Webhook de saída:</b> aviso automático que o ZapZap envia ao seu sistema quando algo acontece."]}],"busca":"glossario glossario administrador (master): usuario com acesso total, inclusive a usuarios, auditoria e versoes. api publica: forma de outros sistemas enviarem mensagens e consultarem o whatsapp usando um token. assinatura: nome em negrito na primeira linha de toda mensagem enviada por um usuario ou token (*nome:*). atendimento: conversa em fila, que pode estar aguardando, em atendimento ou resolvida. auditoria: registro de quem fez o que, quando e de onde. conexao: um numero de whatsapp ligado ao painel. tambem chamada de instancia. csv: arquivo de planilha simples, que abre no excel ou google planilhas. escopo: permissao de um token de api (enviar texto, enviar midia, ver status, ler mensagens). etiqueta: marcador colorido aplicado a conversas. jid: identificador interno de uma conversa no whatsapp (numero ou grupo). nota interna: anotacao da equipe sobre um contato; o contato nunca a recebe. permissao: autorizacao individual de um usuario para uma acao ou tela. perfil rapido: conjunto de permissoes pronto (atendente, somente leitura, gerente). qr code: imagem que o whatsapp do celular le para conectar o numero ao painel. resposta rapida: texto pronto, chamado por um atalho com /. segredo (webhook): codigo usado para conferir que um aviso veio mesmo do zapzap. sessao: acesso aberto de um usuario em um aparelho. dura ate 30 dias ou ate ser encerrada. token: chave de acesso da api publica, mostrada uma unica vez ao ser criada. webhook de saida: aviso automatico que o zapzap envia ao seu sistema quando algo acontece."}]}];
  const ICONES = { 1: 'fa-rocket', 2: 'fa-qrcode', 3: 'fa-comments', 4: 'fa-headset', 5: 'fa-paper-plane', 6: 'fa-clock', 7: 'fa-wand-magic-sparkles', 8: 'fa-robot', 9: 'fa-bullhorn', 10: 'fa-address-book', 11: 'fa-chart-column', 12: 'fa-clock-rotate-left', 13: 'fa-plug-circle-bolt', 14: 'fa-user-gear', 15: 'fa-shield-halved', 16: 'fa-gear', 17: 'fa-life-ring', 18: 'fa-book' };
  const semAcento = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const TOP = {}; DADOS.forEach(s => s.topicos.forEach(t => { t.sec = s; TOP[t.id] = t; }));
  const TODOS = DADOS.reduce((a, s) => a.concat(s.topicos), []);
  const base = () => (document.querySelector('base') ? '' : '');
  const selo = t => t.admin ? '<span class="aj-selo"><i class="fa-solid fa-user-shield"></i> Administrador</span>' : '';
  let raiz = null, q = '';

  function blocoHtml(b) {
    if (b.t === 'p') return `<p>${b.h}</p>`;
    if (b.t === 'nota') return `<div class="aj-nota aj-${b.tipo}"><i class="fa-solid ${b.tipo === 'dica' ? 'fa-lightbulb' : 'fa-triangle-exclamation'}"></i><span>${b.h}</span></div>`;
    if (b.t === 'ul') return `<ul class="aj-ul">${b.itens.map(i => `<li>${i}</li>`).join('')}</ul>`;
    if (b.t === 'cod') return `<pre class="aj-cod"><code>${ZZ.esc(b.c)}</code></pre>`;
    if (b.t === 'img') return imgHtml(b.src, b.alt);
    if (b.t === 'ol') return `<ol class="aj-ol">${b.itens.map(i => `<li><div class="aj-passo">${i.h}</div>${i.img ? imgHtml(i.img, i.alt) : ''}</li>`).join('')}</ol>`;
    return '';
  }
  const imgHtml = (src, alt) => `<figure class="aj-fig"><img src="${ZZ.esc(src)}?v=${ZZ.v}" alt="${ZZ.esc(alt)}" loading="lazy" decoding="async" data-zoom><figcaption>${ZZ.esc(alt)}</figcaption></figure>`;

  /* ---------- telas ---------- */
  function topo(extra) {
    return `<div class="card-soft aj-topo"><div class="aj-busca"><i class="fa-solid fa-magnifying-glass"></i><input type="search" id="ajQ" placeholder="Buscar no manual…" value="${ZZ.esc(q)}" autocomplete="off" enterkeyhint="search" aria-label="Buscar no manual"></div>${extra || ''}</div>`;
  }
  function telaIndice() {
    const cards = DADOS.map(s => `<button class="aj-card" data-s="${s.n}"><span class="aj-ic"><i class="fa-solid ${ICONES[s.n] || 'fa-circle-question'}"></i></span><span class="aj-ct"><b>${s.n}. ${ZZ.esc(s.titulo)}</b><small>${s.topicos.length} ${s.topicos.length === 1 ? 'tópico' : 'tópicos'}</small></span><i class="fa-solid fa-chevron-right"></i></button>`).join('');
    raiz.innerHTML = `${topo(`<button class="btn-azul aj-tela" id="ajTela"><i class="fa-solid fa-expand"></i> Abrir o tutorial em tela cheia</button>`)}<div id="ajRes"></div><div class="aj-grade" id="ajIdx">${cards}</div><p class="mut aj-rodape">Manual completo (com imagens) também em <b>docs/MANUAL.md</b> no repositório. Imagens com dados fictícios.</p>`;
    ligarBusca();
    ZZ.$('#ajTela', raiz).onclick = () => tutorial(DADOS[0].topicos[0].id, DADOS[0].topicos);
    ZZ.$$('.aj-card', raiz).forEach(b => b.onclick = () => ZZ.ir('ajuda', { s: b.dataset.s }));
  }
  function telaSecao(n) {
    const s = DADOS.find(x => x.n === +n); if (!s) return telaIndice();
    raiz.innerHTML = `${topo()}<div id="ajRes"></div><div id="ajCorpo"><button class="btn-soft aj-volta" data-v><i class="fa-solid fa-arrow-left"></i> Todos os assuntos</button>
      <h2 class="aj-h2"><i class="fa-solid ${ICONES[s.n] || 'fa-circle-question'}"></i> ${s.n}. ${ZZ.esc(s.titulo)}</h2>
      <div class="aj-lista">${s.topicos.map(t => `<button class="aj-item" data-t="${t.id}"><span class="aj-it"><b>${ZZ.esc(t.titulo)}</b>${selo(t)}</span><i class="fa-solid fa-chevron-right"></i></button>`).join('')}</div></div>`;
    ligarBusca(); ZZ.$('[data-v]', raiz).onclick = () => ZZ.ir('ajuda');
    ZZ.$$('.aj-item', raiz).forEach(b => b.onclick = () => ZZ.ir('ajuda', { t: b.dataset.t }));
  }
  function telaTopico(id) {
    const t = TOP[id]; if (!t) return telaIndice();
    const s = t.sec, i = s.topicos.indexOf(t), ant = s.topicos[i - 1], prox = s.topicos[i + 1];
    raiz.innerHTML = `${topo()}<div id="ajRes"></div><article id="ajCorpo" class="card-soft aj-art"><button class="btn-soft aj-volta" data-v><i class="fa-solid fa-arrow-left"></i> ${s.n}. ${ZZ.esc(s.titulo)}</button>
      <h2 class="aj-h2">${ZZ.esc(t.titulo)}</h2>${selo(t)}<div class="aj-txt">${t.blocos.map(blocoHtml).join('')}</div>
      <div class="aj-nav">${ant ? `<button class="btn-soft" data-t="${ant.id}"><i class="fa-solid fa-chevron-left"></i> ${ZZ.esc(ant.titulo)}</button>` : '<span></span>'}${prox ? `<button class="btn-azul" data-t="${prox.id}">${ZZ.esc(prox.titulo)} <i class="fa-solid fa-chevron-right"></i></button>` : ''}</div>
      <button class="btn-soft aj-tela2" id="ajTela"><i class="fa-solid fa-expand"></i> Abrir o tutorial em tela cheia</button></article>`;
    ligarBusca(); ZZ.$('[data-v]', raiz).onclick = () => ZZ.ir('ajuda', { s: s.n });
    ZZ.$$('.aj-nav [data-t]', raiz).forEach(b => b.onclick = () => ZZ.ir('ajuda', { t: b.dataset.t }));
    ZZ.$('#ajTela', raiz).onclick = () => tutorial(t.id, [t]);
    ZZ.$$('img[data-zoom]', raiz).forEach(im => im.onclick = () => ampliar(im));
    const a = ZZ.$('#pagina'); if (a) a.scrollTop = 0; window.scrollTo(0, 0);
  }
  function ampliar(im) {
    const m = ZZ.modal(`<div class="aj-zoom"><img src="${ZZ.esc(im.src)}" alt="${ZZ.esc(im.alt)}"></div><div class="acoes"><button class="btn-azul" data-f>Fechar</button></div>`);
    m.el.querySelector('[data-f]').onclick = () => m.fechar();
  }

  /* ---------- busca ---------- */
  function ligarBusca() {
    const inp = ZZ.$('#ajQ', raiz);
    inp.oninput = ZZ.debounce(() => { q = inp.value; pintarBusca(); }, 200);
    if (q) pintarBusca();
  }
  function pintarBusca() {
    const res = ZZ.$('#ajRes', raiz); if (!res) return; const termos = semAcento(q).split(/\s+/).filter(Boolean);
    const outros = ZZ.$('#ajIdx', raiz) || ZZ.$('#ajCorpo', raiz);
    if (!termos.length) { res.innerHTML = ''; if (outros) outros.hidden = false; return; }
    const achados = TODOS.filter(t => termos.every(x => t.busca.includes(x))).slice(0, 30);
    if (outros) outros.hidden = true;
    res.innerHTML = achados.length ? `<div class="mut aj-qtd">${achados.length} ${achados.length === 1 ? 'resultado' : 'resultados'}</div><div class="aj-lista">${achados.map(t => `<button class="aj-item" data-t="${t.id}"><span class="aj-it"><b>${ZZ.esc(t.titulo)}</b><small class="mut">${t.sec.n}. ${ZZ.esc(t.sec.titulo)}</small>${selo(t)}</span><i class="fa-solid fa-chevron-right"></i></button>`).join('')}</div>`
      : '<div class="vazio"><i class="fa-solid fa-magnifying-glass"></i>Nada encontrado. Tente outra palavra.</div>';
    ZZ.$$('.aj-item', res).forEach(b => b.onclick = () => ZZ.ir('ajuda', { t: b.dataset.t }));
  }

  /* ---------- tutorial em tela cheia (um passo por vez) ---------- */
  function slides(lista) {
    const r = [];
    lista.forEach(t => {
      const intro = t.blocos.filter(b => b.t === 'p').slice(0, 1).map(b => b.h).join('');
      r.push({ tit: t.titulo, sec: t.sec.titulo, h: intro, adm: t.admin, capa: true });
      t.blocos.forEach(b => {
        if (b.t === 'ol') b.itens.forEach((it, k) => r.push({ tit: t.titulo, sec: t.sec.titulo, n: k + 1, de: b.itens.length, h: it.h, img: it.img, alt: it.alt }));
        else if (b.t === 'nota') r.push({ tit: t.titulo, sec: t.sec.titulo, nota: b.tipo, h: b.h });
        else if (b.t === 'img') r.push({ tit: t.titulo, sec: t.sec.titulo, h: '', img: b.src, alt: b.alt });
      });
    });
    return r;
  }
  function tutorial(id, lista) {
    const S = slides(lista); let i = 0;
    const ov = document.createElement('div'); ov.className = 'aj-full'; ov.setAttribute('role', 'dialog'); ov.setAttribute('aria-modal', 'true');
    ov.innerHTML = `<div class="aj-f-topo"><button class="aj-f-x" aria-label="Fechar tutorial"><i class="fa-solid fa-xmark"></i></button><div class="aj-f-tt"><b id="afT"></b><small id="afS"></small></div><span class="mut" id="afC"></span></div>
      <div class="barra-prog aj-f-barra"><i id="afB"></i></div><div class="aj-f-corpo" id="afCorpo"></div>
      <div class="aj-f-rod"><button class="btn-soft" id="afA"><i class="fa-solid fa-chevron-left"></i> Anterior</button><button class="btn-azul" id="afP">Próximo <i class="fa-solid fa-chevron-right"></i></button></div>`;
    document.body.appendChild(ov); ZZ.modalAberto = (ZZ.modalAberto || 0) + 1; document.documentElement.classList.add('aj-travado');
    const fechar = () => { document.removeEventListener('keydown', tecla); ov.remove(); ZZ.modalAberto = Math.max(0, (ZZ.modalAberto || 1) - 1); document.documentElement.classList.remove('aj-travado'); };
    const tecla = e => { if (e.key === 'Escape') fechar(); else if (e.key === 'ArrowRight') ir(1); else if (e.key === 'ArrowLeft') ir(-1); };
    const pintar = () => {
      const s = S[i]; ZZ.$('#afT', ov).textContent = s.tit; ZZ.$('#afS', ov).textContent = s.sec; ZZ.$('#afC', ov).textContent = (i + 1) + ' / ' + S.length;
      ZZ.$('#afB', ov).style.width = ((i + 1) / S.length * 100) + '%';
      const corpo = ZZ.$('#afCorpo', ov);
      corpo.innerHTML = (s.capa ? `<div class="aj-f-capa"><i class="fa-solid fa-circle-play"></i>${s.adm ? '<span class="aj-selo"><i class="fa-solid fa-user-shield"></i> Administrador</span>' : ''}<h2>${ZZ.esc(s.tit)}</h2><p>${s.h}</p></div>`
        : `${s.n ? `<div class="aj-f-n"><b>${s.n}</b><small>de ${s.de}</small></div>` : ''}${s.nota ? `<div class="aj-nota aj-${s.nota}"><i class="fa-solid ${s.nota === 'dica' ? 'fa-lightbulb' : 'fa-triangle-exclamation'}"></i><span>${s.h}</span></div>` : `<p class="aj-f-txt">${s.h}</p>`}`)
        + (s.img ? `<figure class="aj-fig aj-f-fig"><img src="${ZZ.esc(s.img)}?v=${ZZ.v}" alt="${ZZ.esc(s.alt)}" decoding="async"></figure>` : '');
      corpo.scrollTop = 0;
      ZZ.$('#afA', ov).disabled = i === 0; ZZ.$('#afP', ov).innerHTML = i === S.length - 1 ? 'Concluir <i class="fa-solid fa-check"></i>' : 'Próximo <i class="fa-solid fa-chevron-right"></i>';
    };
    const ir = d => { if (i + d >= S.length) { fechar(); return; } i = Math.max(0, i + d); pintar(); ZZ.vibrar(8); };
    ZZ.$('.aj-f-x', ov).onclick = fechar; ZZ.$('#afA', ov).onclick = () => ir(-1); ZZ.$('#afP', ov).onclick = () => ir(1);
    let x0 = null; ov.addEventListener('touchstart', e => { x0 = e.touches[0].clientX; }, { passive: true });
    ov.addEventListener('touchend', e => { if (x0 === null) return; const dx = e.changedTouches[0].clientX - x0; x0 = null; if (Math.abs(dx) > 70) ir(dx < 0 ? 1 : -1); }, { passive: true });
    document.addEventListener('keydown', tecla); pintar();
  }

  ZZ.ajuda = { abrir: id => ZZ.ir('ajuda', id ? { t: id } : null), topicos: () => TODOS.map(t => ({ id: t.id, titulo: t.titulo })) };
  ZZ.pagina({
    id: 'ajuda', titulo: 'Ajuda', icone: 'fa-circle-question', ordem: 9.8,
    render(el, ctx) {
      raiz = document.createElement('div'); raiz.className = 'aj'; el.appendChild(raiz); q = '';
      const p = (ctx && ctx.params) || {};
      if (p.t && TOP[p.t]) telaTopico(p.t); else if (p.s) telaSecao(p.s); else telaIndice();
    },
    destroy() { raiz = null; const f = document.querySelector('.aj-full'); if (f) f.remove(); document.documentElement.classList.remove('aj-travado'); }
  });
})();
